(function () {
/* A66 staging · exact frozen manifest lurid–makeover (80 lemmas). */
'use strict';
const rawD=globalThis.RA.D;
const E=(origin,word)=>({origin,prefix:null,root:null,suffix:null,history:[],formationLogic:'',mnemonic:null,note:'Uncertain historical details are not inferred beyond the stated origin.',source:'Etymonline — https://www.etymonline.com/word/'+word.toLowerCase().replaceAll(' ','-')});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const quizSenses={lush:[1,2,1,1],lust:[1,2,1,1],luster:[1,2,1,1],luxuriant:[1,2,1,1]};
const D=(w,p)=>rawD(w,{...p,quiz:p.quiz.map((q,i)=>q.id?q:{...q,id:w+'.q'+(i+1),senseId:w+'.s'+(quizSenses[w]?.[i]||Number((p.contexts[0]?.senseId||w+'.s1').split('.s')[1]))})});
const Q=(...a)=>{if(a.length>=9)return {id:a[0]+'.q'+a[1],senseId:a[0]+'.s'+a[2],prompt:a[3],options:[a[4],a[5],a[6]],answer:a[7],explain:a[8],errorType:a[9]||'meaning',type:'辨义与用法'};const full=a.length>=6;return {prompt:a[0],options:[a[1],a[2],a[3]],answer:full?a[4]:a[1],explain:full?a[5]:a[4],errorType:a.length>=7?a[6]:'meaning',type:'辨义与用法'};};
D('lurid',{etymology:E('Lurid comes through French from Latin luridus, “pale yellow”; English developed senses of shocking sensationalism and harsh unnatural brightness.','lurid'),contexts:[C('lurid.s1','报刊报道','The tabloid published a lurid account of the murder, emphasizing graphic details that the police report had left out.','小报刊登了一篇渲染谋杀案的报道，着重描写了警方报告没有提及的血腥细节。','The tabloid published / a lurid account of the murder / emphasizing graphic details / that the police report had left out.','lurid 修饰 account，表示报道以骇人细节吸引注意。','渲染暴力且令人震惊的叙述符合 s1。')],mistakes:[M('The paper called its lurid account mild and restrained even though it dwelt on graphic violence.','The paper published a lurid account that dwelt on graphic violence.','渲染血腥细节与温和克制相矛盾。')],quiz:[Q('lurid',1,1,'A lurid news report tends to?','dwell sensationally on shocking details','omit every detail and remain neutral','give a scientific measurement','dwell sensationally on shocking details','lurid 的报道义强调骇人细节。'),Q('lurid',2,2,'A lurid sunset is?','unnaturally bright or glowing','completely dark','quietly described in a report','unnaturally bright or glowing','lurid 也可描写刺目、不自然的光色。'),Q('lurid',3,1,'Which subject suits a lurid account?','graphic details of a violent crime','a routine bus timetable','a neutral list of office supplies','graphic details of a violent crime','暴力细节常被 sensationally 渲染。'),Q('lurid',4,2,'Which phrase uses the brightness sense?','a lurid orange glow','a lurid legal summary','a lurid pencil count','a lurid orange glow','橘色发出不自然强光，符合 s2。')]});
D('lurk',{etymology:E('Lurk is recorded in English from the late Middle Ages; its remote origin is uncertain, so no specific root is asserted.','lurk'),contexts:[C('lurk.s1','夜间巡查','A fox lurked beneath the garden hedge, waiting for the rabbits to come out after the lights went off.','一只狐狸潜伏在花园树篱下，等着灯熄后兔子出来。','A fox lurked / beneath the garden hedge / waiting for the rabbits / to come out after the lights went off.','lurk 作不及物动词，表示隐蔽地等待；beneath 指藏身位置。','狐狸藏在树篱下伺机而动，符合 s1。')],mistakes:[M('The fox lurked in the open under bright lights, announcing its position to everyone nearby.','The fox hid beneath the hedge and waited unseen.','公开暴露并宣布位置与隐蔽潜伏相反。')],quiz:[Q('To lurk is to wait?','secretly in a hidden place','openly in the middle of a road','at a public desk to file papers','secretly in a hidden place','lurk 表示藏起来等待。'),Q('Where did the fox lurk?','beneath the hedge','on the roof in full view','inside the train station','beneath the hedge','语境地点是花园树篱下。'),Q('What was the fox waiting for?','rabbits to come out','the sun to set in another country','a newspaper to be printed','rabbits to come out','它等兔子出现再行动。'),Q('Which verb is closest to lurk here?','hide and wait','celebrate loudly','travel openly','hide and wait','隐蔽等待最接近该词义。')]});
D('lush',{etymology:E('Lush is recorded in English as a word for thick, luxuriant growth; its deeper history is uncertain.','lush'),contexts:[C('lush.s1','山谷徒步','After weeks of rain, lush grass covered the valley floor and wildflowers grew along the stream.','几周降雨后，青翠茂密的草覆盖了山谷地面，溪边也长满野花。','After weeks of rain / lush grass covered the valley floor / and wildflowers grew / along the stream.','lush 修饰 grass，表示植物浓密且长势健康。','雨后茂盛的绿色植物符合 s1。')],mistakes:[M('The valley had lush grass, meaning the plants were sparse, brown, and dying.','The valley had thick, healthy green growth.','稀疏枯黄与 lush 的茂盛健康相反。')],quiz:[Q('Lush grass is?','thick and healthy','thin and dead','made of metal','thick and healthy','植物义 lush 表示茂密繁盛。'),Q('Which lifestyle may be called lush?','rich and comfortable','poor and uncomfortable','hidden underground','rich and comfortable','lush 也可形容奢华舒适的生活。'),Q('What grew beside the stream?','wildflowers','magazines','mackerel','语境提到溪边野花。'),Q('Which phrase describes the plant sense?','a lush green valley','a lush paper clip','a lush legal hearing','a lush green valley','青翠繁茂的山谷符合植物义。')]});
D('lust',{etymology:E('Lust comes from Old English lust, “desire or pleasure,” and developed strong senses of sexual desire and intense craving.','lust'),contexts:[C('lust.s1','商业伦理','A lust for profit led the executives to ignore safety warnings and put workers at risk.','对利润的强烈渴求使管理者无视安全警告，让工人陷入危险。','A lust for profit / led the executives / to ignore safety warnings / and put workers at risk.','lust 作名词，常与 for 连用，表示对某物的强烈欲望。','为了利润无视安全体现炽烈渴求，符合 s1。')],mistakes:[M('The executives’ lust for profit meant they rejected every opportunity to earn money and cared only about safety.','Their intense craving for profit made them disregard safety.','拒绝利润且只顾安全与 lust for profit 矛盾。')],quiz:[Q('A lust for power is an intense?','craving for power','fear of every machine','lack of interest in anything','craving for power','lust 可表示对权力的强烈渴求。'),Q('To lust after something is to?','feel a strong desire for it','lend it temporarily','measure it carefully','feel a strong desire for it','lust 也可作动词表示强烈欲望。'),Q('What did the executives ignore?','safety warnings','a poem lyric','a rainfall forecast only','safety warnings','语境中他们无视了安全警告。'),Q('Which phrase is a noun use?','a lust for profit','they lusted after land','luster on a pearl','a lust for profit','a lust for profit 中 lust 是名词。')]});
D('luster',{etymology:E('Luster is an American spelling of lustre, from French lustre and ultimately Latin lustrare, “to make bright”; it can also mean honor or distinction.','luster'),contexts:[C('luster.s1','珠宝鉴定','The jeweler turned the pearl under a lamp to examine its soft luster and check that the surface had not been damaged.','珠宝商在灯下转动珍珠，检查它柔和的光泽以及表面是否受损。','The jeweler turned the pearl / under a lamp / to examine its soft luster / and check the surface.','luster 作名词，指光滑表面柔和明亮的反光。','珍珠表面的光泽符合 s1。')],mistakes:[M('The pearl’s luster was its rough darkness that reflected no light at all.','The pearl’s luster was its soft, smooth shine.','完全不反光与表面光泽相反。')],quiz:[Q('A pearl’s luster is its?','smooth surface shine','weight in grams','price on a receipt','smooth surface shine','luster 的常见义是表面光泽。'),Q('A victory can add luster to a school by adding?','honor and distinction','dirt to its classrooms','machinery to its factory','honor and distinction','luster 也可比喻荣誉声望。'),Q('What did the jeweler use to inspect the pearl?','a lamp','a mainsheet','a raincoat','a lamp','语境中珠宝商在灯下检查。'),Q('Which spelling is common in British English?','lustre','lusterer','lustration only','lustre','luster 的英式拼写常为 lustre。')]});
D('lustrous',{etymology:E('Lustrous is formed from luster with the adjective-forming suffix -ous and means gently shining or bright.','lustrous'),contexts:[C('lustrous.s1','织物选购','The silk scarf had a lustrous sheen that caught the window light without looking metallic or harsh.','这条丝巾带有柔和亮泽，在窗光下闪耀，却不显得像金属般刺眼。','The silk scarf had / a lustrous sheen / that caught the window light / without looking metallic or harsh.','lustrous 修饰 sheen，描述平滑明亮而柔和反光的外观。','丝绸柔和反光符合 s1。')],mistakes:[M('The silk looked lustrous because it was dull, rough, and absorbed all the light.','The silk looked lustrous because its smooth surface reflected light gently.','暗淡粗糙且吸光与 lustrous 相反。')],quiz:[Q('A lustrous surface is?','smooth and gently shining','rough and completely lightless','always transparent','smooth and gently shining','lustrous 表示平滑且有光泽。'),Q('What had the lustrous sheen?','a silk scarf','a legal summons','a mackerel bone','a silk scarf','语境中有光泽的是丝巾。'),Q('Which suffix appears in lustrous?','-ous','-less','-ment','-ous','lustrous 由 luster 加 -ous 构成。','word-formation'),Q('A lustrous finish should not look?','harsh and metallic','smooth and bright','softly reflective','harsh and metallic','语境突出柔和光泽而非刺眼金属感。')]});
D('lusty',{etymology:E('Lusty derives from Middle English lusti, related to Old Norse lyst, “desire or pleasure”; it now commonly means vigorous and hearty.','lusty'),contexts:[C('lusty.s1','婴儿健康','The newborn gave a lusty cry as the nurse wrapped him in a warm blanket and handed him to his mother.','护士把新生儿裹进暖毯并交给母亲时，他发出了洪亮有力的哭声。','The newborn gave / a lusty cry / as the nurse wrapped him / in a warm blanket.','lusty 修饰 cry，表示声音洪亮、有活力。','有力的啼哭符合 s1。')],mistakes:[M('The newborn gave a lusty cry so faint and weak that nobody could hear it.','The newborn gave a strong, hearty cry.','微弱无声与 lusty 的强劲洪亮相反。')],quiz:[Q('A lusty cry is?','strong and hearty','faint and barely audible','a written lyric','strong and hearty','lusty 可形容洪亮有力的声音。'),Q('Which person might be described as lusty?','a vigorous young athlete','a completely exhausted patient','a silent statue','a vigorous young athlete','该词也可形容精力旺盛的人。'),Q('Who wrapped the newborn?','the nurse','a lyricist','a magistrate','语境中护士给婴儿裹毯。'),Q('Lusty can describe a hearty?','appetite','magazine issue','legal appeal','lusty 还可形容胃口旺盛。')]});
D('lutheranism',{etymology:E('Lutheranism is formed from Lutheran, named for Martin Luther, with the noun suffix -ism; it names the Protestant tradition based on his teaching.','lutheranism'),contexts:[C('lutheranism.s1','宗教史课堂','The lecture traced how Lutheranism spread through parts of northern Europe during the sixteenth century.','讲座追溯了路德宗在十六世纪如何传播到北欧部分地区。','The lecture traced / how Lutheranism spread / through parts of northern Europe / during the sixteenth century.','Lutheranism 作专名性宗教名词；how 引出传播过程。','以路德教导为基础的新教传统符合 s1。')],mistakes:[M('The lecture defined Lutheranism as an ancient Greek system of geometry unrelated to Christianity.','It described Lutheranism as a Protestant Christian tradition based on Luther’s teaching.','几何学与路德宗的基督教传统无关。')],quiz:[Q('Lutheranism is a branch of?','Protestant Christianity','Buddhist philosophy','ancient Greek geometry','Protestant Christianity','Lutheranism 是新教传统之一。'),Q('Whose teaching is it based on?','Martin Luther’s','a Greek mathematician’s','a modern lyricist’s','Martin Luther’s','该传统以马丁·路德的教导为基础。'),Q('Where did it spread in the example?','parts of northern Europe','all of South America','the Australian desert','parts of northern Europe','句中说传播至北欧部分地区。'),Q('The suffix -ism commonly helps form a?','noun naming a system or tradition','past-tense verb','comparative adjective','noun naming a system or tradition','-ism 常构成学说或传统的名词。','word-formation')]});
D('luxuriant',{etymology:E('Luxuriant comes from Latin luxurians, “abundant or rank,” from luxuriari, “to grow exuberantly”; it can describe growth or rich style.','luxuriant'),contexts:[C('luxuriant.s1','庭园维护','Luxuriant vines covered the old stone wall, so the gardener trimmed them back before they reached the roof tiles.','茂盛的藤蔓覆盖了旧石墙，因此园丁在它们爬到屋瓦前进行了修剪。','Luxuriant vines covered / the old stone wall / so the gardener trimmed them back / before they reached the roof tiles.','luxuriant 修饰 vines，表示植物长势旺盛、浓密。','爬满墙面的旺盛藤蔓符合 s1。')],mistakes:[M('The luxuriant vines were sparse, brown, and too weak to cover even one stone.','The luxuriant vines grew thickly and covered the wall.','稀疏枯弱与 luxuriant 的繁茂相反。')],quiz:[Q('Luxuriant vines grow?','thickly and strongly','sparsely and weakly','only underground without leaves','thickly and strongly','植物义 luxuriant 表示浓密旺盛。'),Q('A luxuriant writing style may be?','rich in words and imagination','limited to one plain word','a type of soil','rich in words and imagination','luxuriant 也可形容辞藻或想象力丰富。'),Q('What did the vines cover?','an old stone wall','a silk scarf','a magazine rack','an old stone wall','语境中藤蔓覆盖石墙。'),Q('Why did the gardener trim them?','they were growing toward the roof','they had all died','they were a type of fish','藤蔓长得旺盛，快爬到屋顶。')]});
D('luxurious',{etymology:E('Luxurious comes from luxury, ultimately Latin luxuria, “excess or abundance”; it describes exceptional comfort, expense, or quality.','luxurious'),contexts:[C('luxurious.s1','商务旅行','The guests stayed in a luxurious hotel with spacious rooms, attentive service, and a quiet garden overlooking the river.','客人住在一家豪华酒店，房间宽敞、服务周到，还有一座俯瞰河流的宁静花园。','The guests stayed / in a luxurious hotel / with spacious rooms and attentive service / overlooking the river.','luxurious 修饰 hotel，表示舒适昂贵、品质极高。','宽敞房间和周到服务符合 s1。')],mistakes:[M('They chose the luxurious hotel because it was bare, uncomfortable, and offered no service.','They chose the luxurious hotel for its comfort and high-quality service.','简陋不舒适与 luxurious 的含义相反。')],quiz:[Q('A luxurious hotel is usually?','very comfortable and high-quality','unsafe and unfinished','a Protestant tradition','very comfortable and high-quality','luxurious 描写舒适且高档的环境。'),Q('What overlooked the river?','the hotel garden','a courthouse','a mackerel boat','酒店的花园俯瞰河流。'),Q('Which adjective describes exceptional comfort?','luxurious','lurid','lutheran','luxurious','该词指奢华舒适。'),Q('A luxurious object is often also?','expensive','free of all quality','hidden in a hedge','昂贵也是 luxuriously comfortable 常见特点。')]});
D('luxury',{etymology:E('Luxury comes through French from Latin luxuria, “excess or abundance”; it can name great comfort, a nonessential pleasure, or serve as an adjective.','luxury'),contexts:[C('luxury.s2','家庭预算','For the family, a weekend trip was a luxury rather than a necessity, so they saved for it after paying their bills.','对这家人来说，周末旅行是一种享受而非必需品，因此他们在付完账单后才为此存钱。','For the family / a weekend trip was a luxury / rather than a necessity / so they saved for it after paying their bills.','luxury 作表语名词，指令人愉快但非必需的事物；rather than 表示对比。','旅行是可有可无的享受，符合 s2。')],mistakes:[M('They called the weekend trip a luxury because it was an unavoidable daily necessity.','They called it a luxury because it was pleasant but not essential.','必需品与非必要享受相反。')],quiz:[Q('luxury',1,1,'A luxury in sense 2 is something?','pleasant but not really needed','essential for survival every minute','always free and uncomfortable','pleasant but not really needed','luxury 可指令人愉快但并非必需之物。'),Q('luxury',2,1,'To live in luxury is to have?','great comfort','no food or shelter','a job with no income','great comfort','luxury 也可指极大舒适。'),Q('luxury',3,3,'A luxury hotel means a?','very comfortable and expensive hotel','small abandoned hut','school of theology','very comfortable and expensive hotel','luxury 可作定语表示豪华的。'),Q('luxury',4,2,'What did the family pay before saving for the trip?','their bills','a lyricist','a magnet','their bills','语境说明先付账单再存钱。')]});
D('lyric',{etymology:E('Lyric comes through Latin lyricus from Greek lyrikos, “of the lyre”; it can describe songlike poetry or name song words and a short personal poem.','lyric'),contexts:[C('lyric.s2','音乐排练','The singer forgot the lyric halfway through the song, so the pianist repeated the introduction while she found her place.','歌手唱到一半时忘了歌词，于是钢琴师重弹前奏，让她找到唱到的位置。','The singer forgot / the lyric halfway through the song / so the pianist repeated the introduction / while she found her place.','lyric 作可数名词，指一首歌的歌词；the lyric 在此作 forgot 的宾语。','忘记的是歌曲中的词句，符合 s2。')],mistakes:[M('She forgot the lyric, meaning she forgot the melody but remembered every word of the song.','She forgot the words of the song.','lyric 指歌词而不是旋律。')],quiz:[Q('lyric',1,2,'A lyric in a song is its?','words','instrument case','ticket price','words','lyric 的名词义可指歌曲歌词。'),Q('lyric',2,1,'Lyric poetry often expresses?','personal feelings','a machine’s operating speed','legal procedure','personal feelings','抒情诗表达个人情感。'),Q('lyric',3,3,'A short personal poem may be a?','lyric','loam','luster','lyric','lyric 也可指抒情短诗。'),Q('lyric',4,2,'What did the singer forget?','the words halfway through the song','the audience’s address','the key to a machine','the words halfway through the song','语境明确说她忘了歌词。')]});
D('lyrical',{etymology:E('Lyrical is formed from lyric with the adjective suffix -al and describes expressive, emotionally rich writing or speech.','lyrical'),contexts:[C('lyrical.s1','散文评论','Her lyrical description of the river at dawn made the ordinary landscape feel vivid and deeply moving.','她对黎明河流的抒情描写使平常的景色显得鲜活而动人。','Her lyrical description / of the river at dawn / made the ordinary landscape / feel vivid and deeply moving.','lyrical 修饰 description，突出优美而富有情感的表达。','景色描写优美且动情，符合 s1。')],mistakes:[M('Her lyrical description was flat, emotionless, and deliberately stripped of every expressive image.','Her description was lyrical because it expressed feeling in vivid, beautiful language.','平淡无情且无表现力与 lyrical 相反。')],quiz:[Q('lyrical',1,1,'Lyrical writing is often?','expressive and emotionally rich','purely numerical','a type of raincoat','expressive and emotionally rich','lyrical 指富于情感表达的。'),Q('lyrical',2,1,'What did her description depict?','the river at dawn','a legal verdict','a mackerel recipe','the river at dawn','语境中的描写对象是黎明的河流。'),Q('lyrical',3,1,'Which noun is modified by lyrical?','description','magnet','mainland','description','lyrical 修饰 description。'),Q('lyrical',4,1,'Which suffix forms lyrical from lyric?','-al','-less','-ment','-al','lyrical 由 lyric 加 -al 构成。','word-formation')]});
D('lyrically',{etymology:E('Lyrically is formed from lyrical with the adverb suffix -ly and means in an expressive, songlike, or emotionally rich manner.','lyrically'),contexts:[C('lyrically.s1','旅行随笔','The writer described the river lyrically, giving its changing light and quiet bends a gentle musical quality.','作者以抒情的笔调描写河流，为其变化的光线和宁静的弯道赋予柔和的音乐感。','The writer described the river / lyrically / giving its changing light and quiet bends / a gentle musical quality.','lyrically 作方式副词修饰 described，说明描写的表达方式。','文字带有抒情和音乐般的感染力，符合 s1。')],mistakes:[M('The writer described the river lyrically using only dry coordinates and no expressive language.','The writer described it in expressive, musical language.','只有坐标且没有抒情表达与 lyrically 相反。')],quiz:[Q('lyrically',1,1,'To write lyrically is to write?','with expressive, songlike feeling','only as a list of measurements','without any emotion','with expressive, songlike feeling','lyrically 描述富有抒情性的表达方式。'),Q('lyrically',2,1,'What did the writer describe?','the river','a court sentence','a household machine','the river','语境对象是河流。'),Q('lyrically',3,1,'Lyrically modifies which action?','described','river','light','described','lyrically 作方式副词修饰 described。'),Q('lyrically',4,1,'Lyrically is the adverb related to?','lyrical','lurid','liver','lyrical','lyrically 由 lyrical 加 -ly 构成。','word-formation')]});
D('lyricist',{etymology:E('Lyricist is formed from lyric with the agent suffix -ist and names a person who writes song words or lyric poetry.','lyricist'),contexts:[C('lyricist.s1','录音棚合作','The lyricist sent the composer a revised verse before the recording session, changing two lines to fit the melody.','录音前，词作者把修改后的诗节发给作曲家，为了配合旋律改了两行。','The lyricist sent the composer / a revised verse / before the recording session / changing two lines to fit the melody.','lyricist 作主语名词，指写歌词的人；to fit 表示修改目的。','为歌曲写词并配合旋律，符合 s1。')],mistakes:[M('The lyricist wrote the melody but supplied no words for the song.','The lyricist wrote the song’s words and revised them to fit the melody.','只作曲不写词不是该语境中的 lyricist 工作。')],quiz:[Q('lyricist',1,1,'A lyricist writes?','song lyrics','court rulings','machine parts','song lyrics','lyricist 指写歌词的人。'),Q('lyricist',2,1,'What did the lyricist send?','a revised verse','a raincoat','a lizard','a revised verse','语境说她发去修改后的诗节。'),Q('lyricist',3,1,'Why were two lines changed?','to fit the melody','to repair a machine','to measure the mainland','to fit the melody','改词是为了配合旋律。'),Q('lyricist',4,1,'The suffix -ist often names a?','person who does an activity','past action','place of storage','person who does an activity','-ist 常构成表示从业者的名词。','word-formation')]});
D('mac',{etymology:E('Mac is a shortened form of mackintosh, the raincoat named after Scottish chemist Charles Macintosh.','mac'),contexts:[C('mac.s1','雨天出行','He pulled on a yellow mac before cycling to work because the forecast warned of steady rain.','天气预报说会持续下雨，他骑车上班前穿上了一件黄色短雨衣。','He pulled on / a yellow mac / before cycling to work / because the forecast warned of steady rain.','mac 作可数名词，指雨衣，常见于口语。','雨天穿着的黄色雨衣符合 s1。')],mistakes:[M('He wore a mac to keep dry, but it was a summer sandal with no rain protection.','He wore a raincoat to stay dry in the rain.','凉鞋不能防雨，mac 指雨衣。')],quiz:[Q('mac',1,1,'A mac is a kind of?','raincoat','song lyric','farm animal','raincoat','mac 是 raincoat 的简称。'),Q('mac',2,1,'Why did he wear the mac?','rain was forecast','he was going swimming','the room was too warm','rain was forecast','穿雨衣是因为预报有雨。'),Q('mac',3,1,'Which longer word is mac shortened from?','mackintosh','macabre','macaque','mackintosh','mac 是 mackintosh 的缩略说法。','word-formation'),Q('mac',4,1,'Where was he going?','to work by bicycle','to a court hearing by boat','to a music studio on foot','to work by bicycle','语境说他骑车去上班。')]});
D('macabre',{etymology:E('Macabre came into English from French macabre, as in danse macabre, “dance of death”; the word’s deeper origin is uncertain.','macabre'),contexts:[C('macabre.s1','黑色喜剧影评','The film’s macabre humour made the audience laugh at scenes involving ghosts, graves, and exaggerated funeral rituals.','这部电影的黑色幽默让观众对涉及鬼魂、坟墓和夸张葬礼仪式的场景发笑。','The film’s macabre humour / made the audience laugh / at scenes involving ghosts and graves / and exaggerated funeral rituals.','macabre 修饰 humour，表示与死亡相关的阴森可怖色彩。','笑料围绕鬼魂和葬礼，符合 s1。')],mistakes:[M('The film was called macabre because it contained only cheerful birthday parties and picnics.','The film was called macabre because its humour involved death and graves.','纯欢乐生日场景不体现死亡相关的阴森感。')],quiz:[Q('macabre',1,1,'Macabre usually suggests something?','grim and horrifying, often linked to death','bright and cheerful','rich in green plant growth','grim and horrifying, often linked to death','macabre 表示阴森可怖，常涉及死亡。'),Q('macabre',2,1,'What was the film’s macabre humour about?','ghosts and graves','raincoats and bicycles','economic statistics','ghosts and graves','语境列出鬼魂与坟墓。'),Q('macabre',3,1,'Which phrase fits the word?','a macabre funeral scene','a cheerful picnic','a litre of milk','a macabre funeral scene','葬礼场景可带有 macabre 氛围。'),Q('macabre',4,1,'The English word came through which language?','French','Japanese','Swahili','French','macabre 由法语进入英语。','meaning')]});
D('macaque',{etymology:E('Macaque entered English through French macaque; its more remote origin is uncertain.','macaque'),contexts:[C('macaque.s1','野生动物观察','A macaque reached across the picnic table, snatched a piece of fruit, and climbed back onto the stone wall.','一只猕猴伸过野餐桌抓走一块水果，然后爬回石墙上。','A macaque reached across the picnic table / snatched a piece of fruit / and climbed back / onto the stone wall.','macaque 作可数名词，指猕猴属的一种猴。','抢水果并攀爬的猕猴符合 s1。')],mistakes:[M('The macaque at the table was identified as a large ocean fish with fins and gills.','It was identified as a monkey of the macaque genus.','猕猴是灵长类动物，不是海鱼。')],quiz:[Q('macaque',1,1,'A macaque is a kind of?','monkey','fish','songwriter','monkey','macaque 指猕猴属的猴子。'),Q('macaque',2,1,'What did it snatch?','a piece of fruit','a magazine','a magnet','a piece of fruit','语境中猕猴抓走水果。'),Q('macaque',3,1,'Where did it climb back to?','the stone wall','the courtroom bench','the hotel room','the stone wall','它爬回石墙上。'),Q('macaque',4,1,'Which animal is a macaque?','a rhesus monkey','a blue parrot','a mackerel','a rhesus monkey','恒河猴属于猕猴属。')]});
D('macaw',{etymology:E('Macaw entered English through Spanish or Portuguese macao; the ultimate source of the bird name is uncertain.','macaw'),contexts:[C('macaw.s1','雨林生态','A blue macaw perched high in the rainforest canopy, its bright feathers visible above the broad leaves.','一只蓝金刚鹦鹉栖在雨林树冠高处，鲜艳的羽毛在宽大的叶片上方清晰可见。','A blue macaw perched / high in the rainforest canopy / its bright feathers visible / above the broad leaves.','macaw 作可数名词，指大型彩羽鹦鹉；perch 表示栖息。','雨林树冠中的大型彩鹦鹉符合 s1。')],mistakes:[M('The blue macaw was described as a small grey fish living beneath the ocean surface.','It was described as a large brightly coloured parrot.','macaw 是鹦鹉，不是鱼。')],quiz:[Q('macaw',1,1,'A macaw is a large?','brightly coloured parrot','small marine fish','farm sheep','brightly coloured parrot','macaw 指大型彩羽鹦鹉。'),Q('macaw',2,1,'Where was the blue macaw perched?','in the rainforest canopy','in a court file','inside a machine','in the rainforest canopy','语境地点是雨林树冠。'),Q('macaw',3,1,'What made it visible above the leaves?','its bright feathers','a yellow raincoat','its written lyrics','its bright feathers','鲜艳羽毛使它在叶片上方可见。'),Q('macaw',4,1,'Macaws are especially associated with?','South America','the Arctic Ocean','the Alps only','South America','该类鹦鹉原产美洲热带地区。')]});
D('macdonald',{etymology:E('Macdonald is a Scottish family name built from Gaelic Mac, “son of,” and the personal name Donald; McDonald is a common spelling variant.','macdonald'),contexts:[C('macdonald.s1','家族史研究','The historian found Macdonald among the names recorded in the Highland parish register and traced the family’s Scottish roots.','历史学家在高地教区登记册中发现了 Macdonald 这个姓，并追溯了该家族的苏格兰根源。','The historian found Macdonald / among the names recorded / in the Highland parish register / and traced the family’s Scottish roots.','Macdonald 作专有姓氏；found 和 traced 描述史料研究。','登记册中的家族姓氏符合 s1。')],mistakes:[M('The parish register listed Macdonald as a common noun meaning a raincoat rather than a family name.','The register recorded Macdonald as a Scottish family name.','姓氏不能在此解释成普通名词雨衣。')],quiz:[Q('macdonald',1,1,'Macdonald is a family name of?','Scottish origin','South American bird origin','Greek mathematical origin','Scottish origin','Macdonald 是苏格兰来源的姓氏。'),Q('macdonald',2,1,'The name contains Gaelic Mac meaning?','son of','brightly coloured','machine part','son of','Mac 在盖尔语姓名中表示“某人的儿子”。','meaning'),Q('macdonald',3,1,'Which spelling is also common?','McDonald','Macaw','Mackintosh only','McDonald','McDonald 是常见拼写变体。'),Q('macdonald',4,2,'In some word lists Macdonald may informally refer to?','the McDonald’s restaurant chain','a type of monkey','a family register','the McDonald’s restaurant chain','来源条目列有餐饮连锁的非正式用法。')]});
D('machine',{etymology:E('Machine comes through French and Latin machina from Greek mēkhanē, “device or contrivance”; it also developed figurative and industrial verb uses.','machine'),contexts:[C('machine.s3','金属加工','The workshop machined the steel brackets to fit the new bolts, checking each hole with a gauge before assembly.','车间用机床把钢支架加工成适配新螺栓的形状，并在装配前用量规检查每个孔。','The workshop machined the steel brackets / to fit the new bolts / checking each hole / with a gauge before assembly.','machine 作及物动词，表示用机床切削或加工材料。','机床加工钢支架符合动词义 s3。')],mistakes:[M('The workshop machined the brackets by shaping them entirely by hand without using any machine tool.','The workshop used a machine tool to cut the brackets to shape.','不用机床手工加工不符合这里的 machine 动词义。')],quiz:[Q('machine',1,1,'A washing machine is equipment that?','does a job using moving parts','is a political group','is a short poem','does a job using moving parts','machine 的常见名词义是机械设备。'),Q('machine',2,2,'A party machine is an organized group that may work?','with little human feeling','only as a washing appliance','as a wild animal','with little human feeling','machine 可比喻缺少人情味的组织。'),Q('machine',3,3,'To machine a metal part is to?','cut or shape it with machine tools','write song words','cover it with a raincoat','cut or shape it with machine tools','machine 也可作动词表示机加工。'),Q('machine',4,1,'Which item is a machine?','a washing machine','a piece of lyric poetry','a magistrate','a washing machine','洗衣机是用来完成工作的设备。')]});
D('machinery',{etymology:E('Machinery is formed from machine with the collective noun suffix -ery and refers to machines as a group or to their components.','machinery'),contexts:[C('machinery.s1','工厂检修','The factory’s machinery is modern, but engineers still inspect the moving parts every week to prevent breakdowns.','工厂的机器设备很现代化，但工程师仍每周检查活动部件以防故障。','The factory’s machinery is modern / but engineers still inspect / the moving parts / every week.','machinery 作集合名词，通常不可数；is 与其搭配用单数。','机器设备及其部件符合 s1。')],mistakes:[M('The machinery are modern and each machinery have their own weekly inspection.','The machinery is modern and its parts are inspected weekly.','machinery 通常不可数，谓语常用单数，不能直接说 each machinery。')],quiz:[Q('Machinery refers to?','machines considered as a group','one person’s lyric','a currency unit','machines considered as a group','machinery 是机器设备的集合称呼。'),Q('How often are the moving parts inspected?','every week','once every century','only after they are sold','every week','语境说工程师每周检查。'),Q('Which verb agrees with machinery here?','the machinery is modern','the machinery are modern','a machinery are modern','the machinery is modern','machinery 作集合不可数名词时常搭配单数动词。','grammar'),Q('Machinery can also mean?','parts of a machine','a magazine article','a farm animal','parts of a machine','machinery 也指机器的结构部件。')]});
D('mackerel',{etymology:E('Mackerel entered English through Anglo-French or Old French; the deeper history of the fish name is uncertain.','mackerel'),contexts:[C('mackerel.s1','海鲜菜单','The restaurant served grilled mackerel with lemon and herbs, and the waiter explained that the fish had been caught that morning.','餐厅供应配柠檬和香草烤鲭鱼，服务员解释说这种鱼是当天早上捕获的。','The restaurant served / grilled mackerel with lemon and herbs / and the waiter explained / that the fish had been caught that morning.','mackerel 作可数鱼名；复数形式通常与单数同形。','作为海鲜供应的多脂海鱼符合 s1。')],mistakes:[M('The chef served grilled mackerel, a leafy vegetable that grows on dry land.','The chef served grilled mackerel, an oily sea fish.','鲭鱼是海鱼，不是陆生叶菜。')],quiz:[Q('Mackerel is an oily?','food fish','parrot','legal official','food fish','mackerel 指多脂食用鱼。'),Q('How was the mackerel prepared?','grilled with lemon and herbs','printed in a magazine','used to cover a roof','grilled with lemon and herbs','语境给出烤制并配柠檬香草。'),Q('The fish had been caught?','that morning','in the sixteenth century','before the machine existed','that morning','服务员说鱼是当天早上捕获的。'),Q('Which plural is common?','some mackerel','some mackerels only','a mackerel of fish','some mackerel','mackerel 复数常与单数同形。','plural')]});
D('mackintosh',{etymology:E('Mackintosh is an eponym named after Scottish chemist Charles Macintosh, who developed waterproof rubberised fabric for coats.','mackintosh'),contexts:[C('mackintosh.s1','雨天准备','Take a mackintosh on the coastal walk; the forecast says showers may arrive before the group reaches the village.','沿海步行时带上防水外套；天气预报说，在队伍抵达村庄前可能会下阵雨。','Take a mackintosh / on the coastal walk / the forecast says showers may arrive / before the group reaches the village.','mackintosh 作可数名词，指防水布外套。','为防阵雨携带的防水外套符合 s1。')],mistakes:[M('She packed a mackintosh for the rain, but it was a thin paper blouse that dissolved when wet.','She packed a waterproof coat for the rain.','纸衬衫遇水会坏，不是防水外套。')],quiz:[Q('A mackintosh is a?','coat made from waterproof cloth','piece of sheet music','small monkey','coat made from waterproof cloth','mackintosh 指防水布制成的外套。'),Q('Why take it on the walk?','showers may arrive','the sun will be too bright at midnight','the group is going swimming indoors','showers may arrive','语境预报沿途可能下阵雨。'),Q('The name is associated with?','Charles Macintosh','Martin Luther','a battle in Greece','Charles Macintosh','外套名称得自发明者 Charles Macintosh。','meaning'),Q('Which spelling is the surname of the inventor?','Macintosh','Mackarel','Macabre','Macintosh','发明者姓 Macintosh，衣物写 mackintosh。')]});
D('macroeconomics',{etymology:E('Macroeconomics combines macro-, “large-scale,” with economics and studies economy-wide totals and relationships.','macroeconomics'),contexts:[C('macroeconomics.s1','大学课程','Macroeconomics examines national inflation, employment, and output together rather than focusing on the accounts of one company.','宏观经济学综合考察一国的通货膨胀、就业和产出，而不是只关注一家公司的账目。','Macroeconomics examines / national inflation, employment, and output / together rather than focusing / on the accounts of one company.','macroeconomics 作学科名；rather than 引出它与企业层面研究的对比。','研究国家总体经济指标符合 s1。')],mistakes:[M('Macroeconomics studies only the weekly sales of one small shop and ignores national totals.','Macroeconomics studies economy-wide measures such as national output and inflation.','只看单家小店不符合宏观经济学的总体尺度。')],quiz:[Q('Macroeconomics studies?','economy-wide totals and relationships','only one household’s grocery list','the structure of a single machine','economy-wide totals and relationships','macro- 指大尺度，宏观经济学研究总体经济。'),Q('Which indicators are in the example?','inflation, employment, and output','luster, lyric, and lizard','rainfall, tides, and fish only','inflation, employment, and output','语境列出通胀、就业和产出。'),Q('Macroeconomics contrasts with focusing on?','one company’s accounts','a nation’s total output','overall employment','one company’s accounts','它不只研究单个企业。'),Q('The prefix macro- means?','large-scale','very small','without measure','large-scale','macro- 表示大尺度。','word-formation')]});
D('mad',{etymology:E('Mad is an old English adjective recorded in Middle English and related to earlier Germanic forms; its senses include anger, enthusiasm, and uncontrolled behaviour.','mad'),contexts:[C('mad.s1','迟到道歉','She was mad at me for arriving late, but she calmed down after I explained that the bus had broken down.','我迟到让她很生气，但我解释公交车抛锚后，她平静了下来。','She was mad at me / for arriving late / but she calmed down / after I explained the bus had broken down.','mad at someone 表示对某人生气；but 引出情绪缓和。','因迟到而生气符合 s1。')],mistakes:[M('She was mad at me for arriving late, meaning she was delighted and thanked me for the delay.','She was angry with me because I arrived late.','愤怒与高兴道谢的理解相反。')],quiz:[Q('If someone is mad at you, they are?','very angry with you','extremely keen on a hobby','a local court officer','very angry with you','mad at 表示对某人生气。'),Q('He is mad about football means he is?','extremely enthusiastic about it','angry at the football itself','unable to see a match','extremely enthusiastic about it','mad about 可表示非常热衷。'),Q('Drive someone mad can mean make them?','behave wildly or lose control','become a magistrate','write a song','behave wildly or lose control','mad 还有精神失常或行为失控义。'),Q('What made her mad in the example?','the late arrival','a lush valley','a magazine article','the late arrival','语境中她因对方迟到生气。')]});
D('mad about',{etymology:E('Mad about is a phrase using mad in the sense “extremely enthusiastic”; about introduces the person or activity that inspires the enthusiasm.','mad about'),contexts:[C('mad about.s1','网球爱好','She is mad about tennis and watches every major final, even when the match starts late at night.','她非常热爱网球，即使比赛深夜才开始，也会观看每场重要决赛。','She is mad about tennis / and watches every major final / even when the match starts / late at night.','be mad about + 名词表示极度热衷于某事。','持续观看网球决赛体现热爱，符合 s1。')],mistakes:[M('She is mad about tennis, so she refuses to watch it or discuss it with anyone.','She is mad about tennis and eagerly follows its major matches.','完全拒绝关注与极度热衷相矛盾。')],quiz:[Q('To be mad about tennis is to be?','very enthusiastic about it','angry because the court is blue','a tennis official','very enthusiastic about it','该短语表示对网球极度热衷。'),Q('What does she watch?','major tennis finals','magazine printing presses','mackerel fishing only','major tennis finals','语境说她观看重要决赛。'),Q('Which pattern is natural?','mad about music','mad in music at','mad of the music','mad about music','常说 be mad about something。','collocation'),Q('When may she watch a match?','even late at night','only during breakfast','never under any circumstances','even late at night','句中说明她会看深夜比赛。')]});
D('madam',{etymology:E('Madam came through Old French madame, literally “my lady,” from ma “my” and dame “lady”; English uses it as a polite form of address.','madam'),contexts:[C('madam.s1','服务台接待','The receptionist smiled and asked, “Can I help you, madam?” before directing the visitor to the information desk.','接待员微笑着问：“女士，需要帮忙吗？”随后把来访者引到咨询台。','The receptionist smiled / and asked “Can I help you, madam?” / before directing the visitor / to the information desk.','madam 作礼貌称呼，常置于问句末尾；此处不需要知道对方姓名。','接待场景中的礼貌称呼符合 s1。')],mistakes:[M('The receptionist used madam as an insult to tell the visitor that she was unwelcome.','The receptionist used madam as a polite form of address.','该语境中 madam 是礼貌称呼而非侮辱。')],quiz:[Q('Madam is a polite way to address?','a woman whose name you do not use','a group of farm animals','a machine operator only','a woman whose name you do not use','madam 可礼貌称呼不直呼其名的女性。'),Q('Where did the receptionist direct the visitor?','the information desk','the machine workshop','the riverbank','the information desk','语境说来访者被引到咨询台。'),Q('Madam Chair uses madam before?','a woman’s role or title','a measurement unit','a fish name','a woman’s role or title','madam 可置于女性职务头衔前。'),Q('Which punctuation fits the spoken example?','a comma before madam','a hyphen inside madam','an apostrophe in the middle','a comma before madam','称呼置于句末时常用逗号隔开。','grammar')]});
D('madame',{etymology:E('Madame is borrowed from French madame, “my lady,” from ma “my” plus dame “lady,” and remains a respectful title for a woman.','madame'),contexts:[C('madame.s1','法语礼貌称呼','The guide introduced Madame Curie by her French title and explained her scientific work to the visitors.','导游用法语敬称介绍居里夫人，并向游客讲解她的科学工作。','The guide introduced / Madame Curie / by her French title / and explained her scientific work.','Madame 作为法语敬称置于女性姓名前，首字母大写。','姓名前的礼貌法语头衔符合 s1。')],mistakes:[M('The guide placed Madame after Curie as an English plural suffix meaning several women.','The guide used Madame before the woman’s name as a respectful French title.','Madame 是姓名前的敬称，不是复数后缀。')],quiz:[Q('Madame is a respectful title from?','French','Swedish','Greek','French','madame 是法语女性敬称。'),Q('Where does the title appear?','before a woman’s name','after a verb as a tense ending','inside a plural noun','before a woman’s name','法语头衔通常置于姓名前。'),Q('Who was introduced in the example?','Madame Curie','the magistrate’s clerk','a macaw','Madame Curie','语境介绍居里夫人。'),Q('Madame literally contains a word meaning?','lady','machine','mackerel','lady','dame 表示“女士”。','meaning')]});
D('madden',{etymology:E('Madden is formed from mad with the verb-forming suffix -en and means drive someone into anger or distraction.','madden'),contexts:[C('madden.s1','邻里噪声','The constant drip from the ceiling maddened the tenants, who could not sleep until the plumber repaired the pipe.','天花板持续滴水让租户们烦躁不已，直到水管工修好管道他们才睡着。','The constant drip / maddened the tenants / who could not sleep / until the plumber repaired the pipe.','madden 作及物动词，表示使人暴怒或心烦；who 引导定语从句。','持续滴水把租户逼得烦躁，符合 s1。')],mistakes:[M('The constant drip maddened the tenants, making them completely calm and delighted.','The constant drip drove the tenants to anger and distraction.','烦躁暴怒与平静愉快相反。')],quiz:[Q('To madden someone is to?','drive them into rage or distraction','make them fall asleep peacefully','lend them a raincoat','drive them into rage or distraction','madden 表示使人发怒或心烦意乱。'),Q('What maddened the tenants?','a constant drip','a quiet garden','a song lyric','a constant drip','语境中的噪音来源是持续滴水。'),Q('Who repaired the pipe?','the plumber','the lyricist','the magistrate','the plumber','水管工修理管道。'),Q('Which adjective is the base for madden?','mad','magenta','mackerel','mad','madden 由 mad 加 -en 构成。','word-formation')]});
D('madhouse',{etymology:E('Madhouse combines mad and house; by the nineteenth century it was also used figuratively for a noisy, chaotic place.','madhouse'),contexts:[C('madhouse.s1','高峰时段','The station became a madhouse at rush hour, with delayed trains, crowded platforms, and announcements echoing overhead.','高峰时段车站变得一片混乱，列车晚点、站台拥挤，广播声在头顶回荡。','The station became a madhouse / at rush hour / with delayed trains and crowded platforms / and announcements echoing overhead.','madhouse 作表语名词，口语比喻嘈杂混乱的地方。','车站挤满人且状况嘈杂，符合 s1。')],mistakes:[M('The station was a madhouse at rush hour because it was silent, empty, and perfectly orderly.','The station was noisy and confusing at rush hour.','安静空旷有序与 madhouse 的混乱含义相反。')],quiz:[Q('A place called a madhouse is?','noisy and confusing','quiet and empty','a unit for measuring volume','noisy and confusing','madhouse 可比喻嘈杂混乱的场所。'),Q('When was the station a madhouse?','at rush hour','during a silent midnight closure','after it was demolished','at rush hour','语境中的时间是通勤高峰。'),Q('Which detail added to the confusion?','delayed trains and crowded platforms','a quiet garden','a single neat shelf','delayed trains and crowded platforms','列车晚点、站台拥挤造成混乱。'),Q('Madhouse combines which words?','mad and house','magnet and house','madam and mouse','mad and house','该词由 mad 与 house 组合。','word-formation')]});
D('magazine',{etymology:E('Magazine came through French magasin from Italian magazzino and Arabic makhāzin, “storehouses”; the publication sense developed from the idea of a store of information.','magazine'),contexts:[C('magazine.s1','科普阅读','She writes for a science magazine that publishes illustrated articles about new discoveries every month.','她为一本科学杂志撰稿，该杂志每月刊登配有插图的新发现文章。','She writes / for a science magazine / that publishes illustrated articles / about new discoveries every month.','magazine 作可数名词，指定期出版的文章图片刊物。','每月刊载科普文章的出版物符合 s1。')],mistakes:[M('She writes for a science magazine, meaning a rifle part that holds cartridges and cannot contain articles.','She writes for a periodical with articles and photographs.','语境中的写稿刊物是期刊义，不是枪械部件义。')],quiz:[Q('A science magazine is a periodical containing?','articles and photographs','only rifle cartridges','a courtroom sentence','articles and photographs','magazine 的出版物义包含文章和图片。'),Q('A gun magazine holds?','cartridges','monthly articles','magenta ink','cartridges','magazine 也指枪械的弹匣。'),Q('A news magazine programme contains?','several short items','one unchanging photograph','only a long silent film','several short items','magazine 还可指由多个短栏目组成的节目。'),Q('How often does the science magazine publish?','every month','every ten years','only when it rains','every month','语境说明每月出版。')]});
D('magenta',{etymology:E('Magenta, the deep pink-purple colour name, was named after the 1859 Battle of Magenta in Italy, around the time the dye became known.','magenta'),contexts:[C('magenta.s1','海报设计','The designer printed the title in magenta against a black background so the deep pink-purple letters would stand out.','设计师用品红色印标题，并以黑色为背景，让深粉紫色字样更加醒目。','The designer printed the title / in magenta / against a black background / so the deep pink-purple letters would stand out.','magenta 作颜色名词，in magenta 表示使用该颜色印刷。','深粉紫色字样与黑底形成反差，符合 s1。')],mistakes:[M('The title was printed in magenta, a deep pink-purple hue, but the designer described it as colourless.','The title was printed in a deep pink-purple colour.','有明显色调与无色描述相矛盾。')],quiz:[Q('Magenta is a deep?','pink-purple hue','green-brown soil','bright yellow metal','pink-purple hue','magenta 指偏紫的深粉红色。'),Q('What colour was the background?','black','magenta','transparent glass','black','语境说背景为黑色。'),Q('Why use magenta letters?','to make the title stand out','to make it invisible','to imitate a legal stamp','to make the title stand out','深粉紫字样在黑底上更醒目。'),Q('The colour name is linked to a battle in?','Italy','Scotland','Brazil','Italy','名称与意大利 Magenta 战役有关。','meaning')]});
D('magic',{etymology:E('Magic came through Old French and Latin magia from Greek mageia, associated with the Magi; it names supernatural power, performance tricks, or a special quality.','magic'),contexts:[C('magic.s3','城市漫步','For the photographer, the magic of the old city lay in its narrow lanes, warm window light, and unexpected courtyards.','对摄影师来说，老城的魅力在于狭窄巷道、温暖的窗光和意外发现的庭院。','For the photographer / the magic of the old city lay / in its narrow lanes / warm window light, and unexpected courtyards.','magic 作名词，指难以解释的特殊吸引力；lie in 表示魅力所在。','景色构成难以言喻的吸引力，符合 s3。')],mistakes:[M('The magic of the old city meant it had no charm, interest, or attraction for visitors.','The city’s unusual charm gave it a special magic.','完全没有吸引力与 magic 的比喻义相反。')],quiz:[Q('In a story, magic may be a supposed power that?','makes impossible things happen','measures national output','keeps a rifle cartridge','makes impossible things happen','magic 有超自然力量的意思。'),Q('A stage magician performs magic by?','using tricks that conceal how they work','changing the laws of physics for real','writing economic reports','using tricks that conceal how they work','表演魔术依靠手法隐藏诀窍。'),Q('The magic of a city means its?','special, hard-to-explain attraction','exact population count','machine parts','special, hard-to-explain attraction','magic 也可比喻特殊魅力。'),Q('A magic evening may mean an evening that seems?','wonderful or unreal','very ordinary and unpleasant','full of broken machinery','wonderful or unreal','magic 可作形容词表示奇妙的。')]});
D('magical',{etymology:E('Magical is formed from magic with the adjective suffix -al and means like magic, wonderful, or mysterious.','magical'),contexts:[C('magical.s1','节庆夜晚','The children thought the snowy garden looked magical under the lanterns, with every branch edged in soft gold light.','孩子们觉得灯笼映照下的雪后花园仿佛有魔法，每根树枝都镶着柔和的金色光边。','The children thought / the snowy garden looked magical / under the lanterns / with every branch edged in soft gold light.','magical 作表语形容词，描述如魔法般奇妙的景象。','雪景灯光营造神奇梦幻感，符合 s1。')],mistakes:[M('The garden looked magical, meaning plain, dull, and completely ordinary under the lanterns.','The garden looked wonderful and mysterious in the lantern light.','平淡普通与 magical 的奇妙义相反。')],quiz:[Q('A magical scene seems?','wonderful and mysterious','strictly ordinary','a type of machine','wonderful and mysterious','magical 指奇妙如魔法般的。'),Q('What made the garden look magical?','lantern light on snow','a magazine subscription','a court fine','lantern light on snow','灯笼照在雪上营造梦幻效果。'),Q('Which suffix appears in magical?','-al','-ist','-less','-al','magical 由 magic 加 -al 构成。','word-formation'),Q('What colour edged the branches?','soft gold','deep magenta only','bright green','soft gold','语境说枝条边缘泛着柔和金光。')]});
D('magician',{etymology:E('Magician is formed from magic with the agent suffix -ian; it can mean a performer of tricks or a person with powers in fantasy stories.','magician'),contexts:[C('magician.s1','儿童演出','The magician invited a child to inspect the empty hat, then pulled a bright scarf from it while the audience watched.','魔术师请一名孩子检查空帽子，然后在观众注视下从里面拉出一条鲜艳的围巾。','The magician invited a child / to inspect the empty hat / then pulled a bright scarf from it / while the audience watched.','magician 作主语名词，指以戏法娱乐观众的表演者。','帽子里变出围巾的舞台戏法符合 s1。')],mistakes:[M('The magician entertained the audience by showing every secret in advance and performing no tricks.','The magician entertained them with tricks that appeared magical.','没有戏法表演就不能体现表演者的魔术师身份。')],quiz:[Q('A stage magician entertains by?','performing tricks that seem magical','hearing minor court cases','measuring rainfall','performing tricks that seem magical','magician 的表演义是用戏法娱乐观众。'),Q('What did the magician pull from the hat?','a bright scarf','a mackerel','a court order','a bright scarf','语境中的道具是一条鲜艳围巾。'),Q('In a fantasy story, a magician may be?','a person with magic powers','a magazine editor','a machine tool','a person with magic powers','magician 也可指奇幻故事中的有法力者。'),Q('Who inspected the hat?','a child from the audience','the magistrate','the factory engineer','a child from the audience','魔术师请一名孩子检查空帽子。')]});
D('magistrate',{etymology:E('Magistrate comes from Latin magistratus, “public office or magistrate,” related to magister, “chief or master.”','magistrate'),contexts:[C('magistrate.s1','地方法院','The magistrate heard the minor traffic case and ordered the driver to pay a fine for speeding.','治安法官审理了这起轻微交通案件，并判令司机因超速缴纳罚款。','The magistrate heard / the minor traffic case / and ordered the driver / to pay a fine for speeding.','magistrate 作主语名词，指审理地方法院轻罪案件的司法官员。','听取轻微交通案并处罚，符合 s1。')],mistakes:[M('The magistrate heard the minor case but had no civil or judicial role and was only a song performer.','The magistrate acted as a local judicial officer and heard the case.','审案的司法官员不是歌曲表演者。')],quiz:[Q('A magistrate may hear?','minor cases in a local court','only national elections','a song recording session','minor cases in a local court','magistrate 可指审理轻微案件的地方司法官。'),Q('In some countries a magistrate may also be?','a local civil official','a sea fish','a machine component','a local civil official','该词还有地方行政官员义。'),Q('What penalty did the magistrate order?','a fine for speeding','a magazine subscription','a raincoat','a fine for speeding','语境判司机因超速缴罚款。'),Q('Where did the hearing take place?','a local court','a rainforest canopy','a railway carriage','a local court','司法官在地方法院审案。')]});
D('maglev',{etymology:E('Maglev is a blend of magnetic and levitation, named for transport vehicles supported above a guideway by magnetic forces.','maglev'),contexts:[C('maglev.s1','交通科技','The maglev covered the airport route in under ten minutes, gliding above its guideway without ordinary wheels touching the track.','磁悬浮列车不到十分钟就走完机场线路，在导轨上方滑行，普通车轮并未接触轨道。','The maglev covered the airport route / in under ten minutes / gliding above its guideway / without ordinary wheels touching the track.','maglev 作交通方式名词；gliding 补充说明列车运行状态。','磁力悬浮于导轨上方的交通方式符合 s1。')],mistakes:[M('The maglev travelled by dragging ordinary wheels along the track while magnets played no role.','The maglev used magnetic forces to float above its guideway.','普通车轮接触轨道且磁力无关，与磁悬浮特征相反。')],quiz:[Q('A maglev uses magnets to?','float a vehicle above a guideway','make a ship lean','print an image','float a vehicle above a guideway','maglev 依靠磁力悬浮列车。'),Q('Which words form maglev?','magnetic and levitation','magazine and level','magenta and living','magnetic and levitation','maglev 是 magnetic 与 levitation 的合成缩略词。','word-formation'),Q('What route did the train cover quickly?','the airport route','a court corridor','a farm path','the airport route','语境说它运行机场线路。'),Q('What did not touch the track in the example?','ordinary wheels','the guideway','the station roof','ordinary wheels','列车悬浮运行，普通车轮没有接触轨道。')]});
D('magma',{etymology:E('Magma comes from Greek magma, “kneaded mass or ointment”; geology uses it for molten rock beneath Earth’s surface.','magma'),contexts:[C('magma.s1','火山地质','Magma rose through cracks in the crust and collected beneath the volcano before pressure triggered an eruption.','岩浆沿地壳裂缝上升，在火山下方聚集，随后压力引发喷发。','Magma rose / through cracks in the crust / and collected beneath the volcano / before pressure triggered an eruption.','magma 作不可数名词，指地表下的高温液态岩石。','火山下方聚集并可能喷发的岩石熔体符合 s1。')],mistakes:[M('The geologist called the cold solid rock on the surface magma while explaining that it was never molten.','Magma is hot molten rock beneath Earth’s surface.','冷却的固体岩石与地下熔融岩浆相反。')],quiz:[Q('Geological magma is?','hot liquid rock beneath the surface','a coloured magazine','a court official','hot liquid rock beneath the surface','地质义 magma 指地下高温液态岩石。'),Q('What can magma rise through?','cracks in Earth’s crust','the pages of a magazine','a raincoat sleeve','cracks in Earth’s crust','语境说岩浆沿地壳裂缝上升。'),Q('An older pharmacy use of magma refers to?','a thick soft mixture','a magnetic train','a legal fine','a thick soft mixture','该词还有旧药剂学中的稠厚混合物义。'),Q('What event followed pressure buildup?','a volcanic eruption','a court recess','a magazine issue','a volcanic eruption','压力积累后引发火山喷发。')]});
D('magnanimous',{etymology:E('Magnanimous comes from Latin magnanimus, literally “great-souled,” from magnus “great” and animus “spirit or mind.”','magnanimous'),contexts:[C('magnanimous.s1','体育比赛','She was magnanimous in victory, congratulating her rival and praising the difficult match instead of mocking the loss.','她胜利后表现得宽宏大量，向对手道贺并称赞比赛艰难，而没有嘲笑对方落败。','She was magnanimous in victory / congratulating her rival / and praising the difficult match / instead of mocking the loss.','magnanimous 作表语形容词，常用于 in victory，表示对对手宽厚大度。','胜者不羞辱对手而给予赞扬，符合 s1。')],mistakes:[M('The winner was magnanimous by taunting her rival and refusing to acknowledge the close match.','She showed generosity and forgiveness toward her rival after winning.','嘲讽并拒绝肯定对手与宽宏大量相反。')],quiz:[Q('A magnanimous winner is?','generous and forgiving toward a rival','small-minded and vindictive','a local judge','generous and forgiving toward a rival','magnanimous 尤指对对手宽宏大量。'),Q('What did she do after winning?','congratulated her rival','mocked the loss','hid the trophy','congratulated her rival','语境中的胜者向对手道贺。'),Q('Which phrase is natural?','magnanimous in victory','magnanimous of the rainfall to','magnanimous weighs ten litres','magnanimous in victory','magnanimous 常与 in victory 连用。','collocation'),Q('Magnanimous literally suggests?','great-souled','deep pink-purple','hidden in a hedge','great-souled','拉丁构词字面义为“心胸伟大”。','meaning')]});
D('magnate',{etymology:E('Magnate comes from Latin magnas, “great man,” through magnatus, a powerful or important person; modern English often means a wealthy business leader.','magnate'),contexts:[C('magnate.s1','媒体行业','A media magnate bought the regional paper and promised to keep its local reporting team in place.','一位媒体巨头买下了这家地区报纸，并承诺保留其本地报道团队。','A media magnate bought / the regional paper / and promised / to keep its local reporting team in place.','magnate 作可数名词，指富有且有影响力的商界人士。','拥有媒体并影响报业的富商符合 s1。')],mistakes:[M('The media magnate was a powerless volunteer with no wealth or influence in business.','The media magnate was a wealthy, influential business owner.','毫无财富和影响力与 magnate 的含义相反。')],quiz:[Q('A business magnate is usually?','a rich and powerful person','a junior office assistant','a measuring lens','a rich and powerful person','magnate 指有钱有势的商界人士。'),Q('What did the media magnate buy?','a regional newspaper','a mackerel boat','a courtroom','a regional newspaper','语境说他买下地区报纸。'),Q('Which adjective commonly precedes magnate?','media','mackerel','magenta','media','media magnate 是常见搭配。','collocation'),Q('What did he promise to retain?','the local reporting team','the paper’s old machinery only','the magistrate','the local reporting team','他承诺保留本地报道团队。')]});
D('magnesium',{etymology:E('Magnesium is named after Magnesia, a region in Greece associated with mineral magnesia; the element symbol is Mg.','magnesium'),contexts:[C('magnesium.s1','化学实验','The magnesium strip burned with a brilliant white flame during the demonstration, so the students watched from behind the safety screen.','演示中镁条燃烧，发出明亮的白色火焰，因此学生们隔着安全屏观看。','The magnesium strip burned / with a brilliant white flame / during the demonstration / so the students watched from behind the safety screen.','magnesium 作元素名词，strip 表示实验用的镁条。','镁燃烧发出白光符合 s1 的化学性质。')],mistakes:[M('The teacher said magnesium produced a black flame and was a type of song lyric.','Magnesium is a chemical element that burns with a bright white flame.','镁的白色火焰与黑色火焰及歌词类别都不相符。')],quiz:[Q('Magnesium is a?','chemical element','court officer','parrot','chemical element','magnesium 是化学元素。'),Q('What colour was its flame?','white','magenta','dark green','white','镁条燃烧会发出白色火焰。'),Q('What is the element symbol?','Mg','Ma','Mn','Mg','镁的元素符号为 Mg。','spelling'),Q('Why did students watch from behind a screen?','for safety during the demonstration','to read a magazine','to avoid hearing a lyric','for safety during the demonstration','强光和实验过程需要安全防护。')]});
D('magnet',{etymology:E('Magnet came through Latin magnes from Greek magnētis lithos, “stone from Magnesia,” an early name for lodestone.','magnet'),contexts:[C('magnet.s2','艺术节宣传','The annual festival is a magnet for young artists, drawing visitors from nearby towns as well as the local community.','一年一度的艺术节吸引了许多年轻艺术家，既有本地居民，也有附近城镇的游客。','The annual festival / is a magnet for young artists / drawing visitors / from nearby towns and the local community.','magnet 作比喻名词，表示能吸引许多人的人或地方。','艺术节吸引大批艺术家和游客，符合 s2。')],mistakes:[M('The festival was a magnet for visitors because it drove everyone away and attracted nobody.','The festival attracted visitors from the region.','无人被吸引与比喻义 magnet 相反。')],quiz:[Q('A physical magnet attracts?','iron and some other metals','paper and water equally','only wooden objects','iron and some other metals','磁体能吸引铁及某些金属。'),Q('A festival can be a magnet for artists if it?','draws many of them there','repels every visitor','is made of iron','draws many of them there','magnet 的比喻义指吸引人群。'),Q('Which phrase uses the figurative sense?','a magnet for tourists','a magnet picks up pins','a magnetic iron bar','a magnet for tourists','吸引游客的活动是比喻义。'),Q('Who came from nearby towns?','visitors','only the festival staff','the metal pins','visitors','语境说附近城镇的游客也被吸引而来。')]});
D('magnetic',{etymology:E('Magnetic is formed from magnet with the adjective suffix -ic; it describes magnetic attraction and, figuratively, strong personal appeal.','magnetic'),contexts:[C('magnetic.s1','物理课堂','Iron is magnetic, so the teacher demonstrated how a bar magnet could pick up several steel pins from the desk.','铁具有磁性，因此老师演示了条形磁铁如何从桌面吸起几枚钢针。','Iron is magnetic / so the teacher demonstrated / how a bar magnet could pick up / several steel pins from the desk.','magnetic 作表语形容词，表示能够吸引铁的。','铁针被磁铁吸起体现物理义 s1。')],mistakes:[M('Iron is magnetic, so the bar magnet pushes steel pins away and cannot attract them.','Iron is magnetic, so a magnet can attract the steel pins.','磁性在此表现为吸引钢铁，不是排斥且无法吸引。')],quiz:[Q('Magnetic iron can be attracted by a?','magnet','mackerel','lyricist','magnet','magnetic 指有磁性的。'),Q('A magnetic speaker may figuratively be?','strongly attractive to people','made entirely of iron','unable to hold an audience','strongly attractive to people','magnetic 也可比喻很有魅力。'),Q('What did the bar magnet pick up?','steel pins','paper magazines','a magistrate','steel pins','语境中的物体是钢针。'),Q('Which suffix appears in magnetic?','-ic','-ist','-hood','-ic','magnetic 由 magnet 加 -ic 构成。','word-formation')]});
D('magnetise',{etymology:E('Magnetise is the British spelling of magnetize, formed from magnet with the verb suffix -ise; it can mean impart magnetism or attract attention.','magnetise'),contexts:[C('magnetise.s2','演讲现场','The speaker magnetised the hall with a vivid account of the rescue, holding the audience’s attention until the final sentence.','演讲者用生动的救援故事牢牢吸引了全场注意力，让听众一直专注到最后一句。','The speaker magnetised the hall / with a vivid account of the rescue / holding the audience’s attention / until the final sentence.','magnetise 作比喻及物动词，表示像磁铁一样吸引注意力。','演讲吸引住全场听众，符合 s2。')],mistakes:[M('The speaker magnetised the hall by boring the audience until everyone left and nobody paid attention.','The speaker held the audience’s attention with a vivid account.','让听众厌烦离场与吸引注意力相反。')],quiz:[Q('To magnetise a piece of metal is to?','make it become a magnet','remove every trace of metal','turn it into a magazine','make it become a magnet','magnetise 的物理义是使金属具有磁性。'),Q('A speaker magnetised the hall means the speaker?','held everyone’s interest','made the room physically smaller','caused every listener to leave','held everyone’s interest','该词也可比喻吸住人的注意力。'),Q('What is the British spelling?','magnetise','magnetizee','magnetize only','magnetise','英式常拼作 magnetise。','spelling'),Q('What held the audience’s attention?','a vivid rescue story','a broken machine','a quiet empty room','a vivid rescue story','生动的救援故事吸引听众。')]});
D('magnetism',{etymology:E('Magnetism is formed from magnet with -ism and names the physical force or science of magnetic attraction, as well as personal appeal.','magnetism'),contexts:[C('magnetism.s2','政治演讲','The young leader’s magnetism helped win over undecided voters, who stayed after the speech to ask questions.','这位年轻领导人的个人魅力赢得了犹豫不决的选民，演讲后他们还留下来提问。','The young leader’s magnetism / helped win over undecided voters / who stayed after the speech / to ask questions.','magnetism 作名词，指吸引他人的个人魅力；helped win over 表示赢得支持。','演讲者吸引并打动选民，符合 s2。')],mistakes:[M('The leader’s magnetism repelled every voter and made the audience leave before the speech began.','The leader’s personal appeal attracted voters and held their interest.','使人离场与个人吸引力相反。')],quiz:[Q('Physical magnetism is the power to attract?','iron and steel','paper and cloth','water vapour','iron and steel','magnetism 的物理义是吸引铁钢的性质。'),Q('A person with magnetism has?','power to attract others','a metal ring in every pocket','no influence on anyone','power to attract others','magnetism 也指个人魅力。'),Q('Who stayed to ask questions?','undecided voters','the factory machinery','the mackerel','undecided voters','语境中犹豫选民留下提问。'),Q('What suffix forms magnetism from magnet?','-ism','-ful','-less','-ism','magnetism 由 magnet 加 -ism 构成。','word-formation')]});
D('magnetize',{etymology:E('Magnetize is the American spelling of magnetise, formed from magnet with the verb suffix -ize; it can also mean attract people powerfully.','magnetize'),contexts:[C('magnetize.s1','科学演示','The coil will magnetize the iron core when an electric current passes through it, turning the core into a temporary magnet.','电流通过线圈时，线圈会使铁芯磁化，把铁芯变成临时磁体。','The coil will magnetize the iron core / when an electric current passes through it / turning the core / into a temporary magnet.','magnetize 作及物动词，表示赋予物体磁性；when 引出发生条件。','电流使铁芯获得磁性符合 s1。')],mistakes:[M('The coil magnetized the iron core by removing its magnetic properties and making it permanently nonmagnetic.','The coil gave the iron core magnetic properties.','去除磁性与使其磁化相反。')],quiz:[Q('To magnetize an iron core is to?','give it magnetic properties','melt it into a liquid','make it a written publication','give it magnetic properties','magnetize 的物理义是使物体有磁性。'),Q('What passes through the coil?','an electric current','a mackerel','a mail parcel','an electric current','电流通过线圈后使铁芯磁化。'),Q('Which spelling is American?','magnetize','magnetise','magnetiseing','magnetize','美式常拼作 magnetize。','spelling'),Q('A speaker can magnetize a crowd by?','drawing people with powerful charm','turning the crowd into iron','making everyone leave','drawing people with powerful charm','该词还有以魅力吸引人群的比喻义。')]});
D('magnetosphere',{etymology:E('Magnetosphere combines magnet and sphere and names the region around a planet dominated by its magnetic field.','magnetosphere'),contexts:[C('magnetosphere.s1','行星科学','Earth’s magnetosphere deflects much of the solar wind, helping shield the planet from charged particles.','地球磁层会偏转大部分太阳风，帮助保护地球免受带电粒子的影响。','Earth’s magnetosphere / deflects much of the solar wind / helping shield the planet / from charged particles.','magnetosphere 作主语名词，指由行星磁场主导的空间区域。','偏转太阳风并屏蔽带电粒子符合 s1。')],mistakes:[M('Earth’s magnetosphere is the region with no magnetic field that intensifies the solar wind at the surface.','It is the region dominated by Earth’s magnetic field that deflects much of the solar wind.','磁层由磁场主导并帮助偏转太阳风，不是无磁场区域。')],quiz:[Q('A planet’s magnetosphere is dominated by its?','magnetic field','ocean currents','paper publications','magnetic field','magnetosphere 是行星磁场主导的空间。'),Q('What does Earth’s magnetosphere help deflect?','solar wind','rainwater from a roof','magazine pages','solar wind','地球磁层会偏转太阳风。'),Q('Which particles are mentioned?','charged particles','wooden particles','song lyrics','charged particles','语境提及带电粒子。'),Q('The word combines magnet with?','sphere','sail','sheet','sphere','magnetosphere 由 magnet 与 sphere 组合。','word-formation')]});
D('magnification',{etymology:E('Magnification is formed from magnify with the noun-forming suffix -cation and refers to how much larger an image appears through a lens.','magnification'),contexts:[C('magnification.s1','显微镜使用','The lens has a magnification of ten, making a tiny cell appear ten times larger than it does to the unaided eye.','这枚透镜的放大倍数是十倍，能使微小细胞看起来比肉眼所见大十倍。','The lens has / a magnification of ten / making a tiny cell appear / ten times larger than it does to the unaided eye.','magnification 作名词，of ten 表示放大倍数；ten times larger 作程度比较。','透镜使图像放大十倍符合 s1。')],mistakes:[M('A magnification of ten made the cell appear one tenth of its original size.','A magnification of ten made the image appear ten times larger.','十倍放大与缩小到十分之一方向相反。')],quiz:[Q('Magnification tells how many times larger an image appears through a?','lens','mailbox','courtroom','lens','magnification 常描述透镜放大倍数。'),Q('What was the magnification in the example?','ten','one tenth','one hundred thousand','ten','语境明确为十倍。'),Q('What appeared larger?','a tiny cell','a whole planet','a mailman','a tiny cell','显微镜放大了微小细胞的图像。'),Q('Magnification is the noun related to?','magnify','magnetise only','madden','magnify','magnification 与动词 magnify 相关。','word-formation')]});
D('magnificence',{etymology:E('Magnificence comes through French from Latin magnificentia, “grandeur or splendor,” related to magnificus.','magnificence'),contexts:[C('magnificence.s1','宫殿参观','They stood in silence before the magnificence of the palace, taking in its vast hall, carved columns, and painted ceiling.','他们在宫殿的壮丽景象前静静驻足，欣赏宽阔大厅、雕花立柱和壁画天花板。','They stood in silence / before the magnificence of the palace / taking in its vast hall / carved columns, and painted ceiling.','magnificence 作介词 before 的名词宾语，指宏伟壮观的特质。','宏伟宫殿的整体气派符合 s1。')],mistakes:[M('The visitors admired the magnificence of the palace, which was tiny, plain, and unimpressive.','They admired the palace’s grand and impressive quality.','狭小平庸与 magnificence 的壮丽气派相反。')],quiz:[Q('Magnificence is the quality of being?','grand and impressive','small and ordinary','unreadable','grand and impressive','magnificence 指壮观气派的特质。'),Q('What did the visitors admire?','the palace','a steel pin','a magazine cartridge','the palace','语境中的对象是宫殿。'),Q('Which feature was part of the palace’s magnificence?','carved columns','a broken raincoat','a court fine','carved columns','雕刻立柱构成宫殿的宏伟装饰。'),Q('Magnificence is related to which adjective?','magnificent','magnetic','macabre','magnificent','magnificence 是 magnificent 的名词。','word-formation')]});
D('magnificent',{etymology:E('Magnificent comes from Latin magnificus, “doing great things or splendid,” from magnus “great” and facere “to make.”','magnificent'),contexts:[C('magnificent.s2','音乐会评论','The orchestra gave a magnificent performance, keeping a delicate balance between the quiet opening and the powerful final movement.','乐团的演出极为出色，在安静的开场与有力的终章之间保持了细腻的平衡。','The orchestra gave / a magnificent performance / keeping a delicate balance / between the quiet opening and the powerful final movement.','magnificent 修饰 performance，表示技艺或质量极其出色。','演奏水准令人赞叹，符合 s2。')],mistakes:[M('The orchestra’s magnificent performance was clumsy, badly played, and disappointing throughout.','The orchestra gave an extremely skillful and impressive performance.','笨拙失败与 magnificent 的赞叹义相反。')],quiz:[Q('A magnificent palace is?','very grand and beautiful','small and poorly built','a magnetic train','very grand and beautiful','magnificent 可描述宏伟美丽的外观。'),Q('A magnificent performance is?','extremely good in quality or skill','a routine failure','a weekly publication','extremely good in quality or skill','该词也可评价技艺质量极佳。'),Q('Who performed magnificently?','the orchestra','the post office','the mackerel','the orchestra','语境主语是乐团。'),Q('What did the performance balance?','a quiet opening and powerful finale','a legal case and a court fee','a metal ring and a lens','a quiet opening and powerful finale','演出平衡了安静开场与有力终章。')]});
D('magnifier',{etymology:E('Magnifier is formed from magnify with the agent or instrument suffix -er and names a lens that enlarges small things.','magnifier'),contexts:[C('magnifier.s1','档案查阅','The archivist used a magnifier to read the tiny handwritten note without touching the fragile paper.','档案员用放大镜阅读微小的手写便条，没有触碰脆弱的纸张。','The archivist used / a magnifier / to read the tiny handwritten note / without touching the fragile paper.','magnifier 作工具名词，指让小字看起来更大的透镜。','借助透镜查看微小字迹符合 s1。')],mistakes:[M('The archivist used a magnifier that made the tiny writing look smaller and harder to see.','The magnifier made the small writing appear larger.','放大镜使小字变大，不是变小。')],quiz:[Q('A magnifier is a lens that makes small things look?','bigger','farther away only','less visible','bigger','magnifier 是放大小物体的透镜。'),Q('What did the archivist read?','a tiny handwritten note','a large street sign','a mackerel label only','a tiny handwritten note','她用放大镜读微小手写便条。'),Q('Why did the archivist avoid touching the paper?','it was fragile','it was made of iron','it was a live animal','it was fragile','档案纸张脆弱，所以不直接触碰。'),Q('The suffix -er here names an?','instrument','past tense','adjective quality','instrument','magnifier 指执行放大功能的工具。','word-formation')]});
D('magnify',{etymology:E('Magnify comes from Latin magnificare, “make great,” formed from magnus “great” and facere “to make”; English uses it literally and figuratively.','magnify'),contexts:[C('magnify.s2','谣言传播','The rumour magnified their fear, making a minor delay sound like proof that the entire project had failed.','谣言夸大了他们的恐惧，把一次小小的延误说成整个项目失败的证据。','The rumour magnified their fear / making a minor delay sound / like proof / that the entire project had failed.','magnify 作及物动词，表示把问题或情绪说得比实际更严重。','小延误被夸张成全面失败，符合 s2。')],mistakes:[M('The rumour magnified their fear by accurately showing that the delay was minor and posed no threat.','The rumour exaggerated the fear by making a small delay seem disastrous.','如实说明风险很小不会夸大恐惧。')],quiz:[Q('A lens can magnify text by making it appear?','larger than it is','more important to the reader','less visible','larger than it is','magnify 的本义是使图像看起来更大。'),Q('A rumour can magnify fear by?','making a small problem seem greater','measuring a problem accurately','removing all uncertainty','making a small problem seem greater','比喻义是夸大问题或情绪。'),Q('What minor event did the rumour exaggerate?','a delay','a palace performance','a mail delivery','a delay','语境中的小事是项目延误。'),Q('Which sense is tested by a magnifying lens?','literal enlargement','emotional exaggeration','pompous speech','literal enlargement','透镜使图像变大，是字面义。')]});
D('magniloquent',{etymology:E('Magniloquent comes from Latin magniloquus, “speaking grandly,” from magnus “great” and loqui “to speak.”','magniloquent'),contexts:[C('magniloquent.s1','竞选演讲','The candidate’s magniloquent speech promised a glorious new era but offered few practical details about the budget.','候选人的演讲措辞浮夸，承诺开启辉煌新时代，却几乎没有提供预算方面的实际细节。','The candidate’s magniloquent speech / promised a glorious new era / but offered few practical details / about the budget.','magniloquent 修饰 speech，表示说话高调夸张、言辞浮华。','宏大承诺而缺乏实质内容，符合 s1。')],mistakes:[M('The speaker was magniloquent because she used plain, modest language and avoided grand claims.','She was magniloquent because she used lofty, pompous language.','朴素克制与言辞浮夸相反。')],quiz:[Q('A magniloquent speaker uses?','lofty and pompous language','brief plain statements','only numerical tables','lofty and pompous language','magniloquent 指说话风格高大浮夸。'),Q('What did the candidate promise?','a glorious new era','a new fish species','a shorter magazine','a glorious new era','语境中的承诺措辞宏大。'),Q('What was missing from the speech?','practical budget details','grand claims','a loud microphone','practical budget details','演讲缺少预算方面的实际细节。'),Q('Magniloquent is related to Latin words for great and?','speak','soil','mail','speak','loqui 意为说话。','meaning')]});
D('magnitude',{etymology:E('Magnitude comes from Latin magnitudo, “greatness or size,” from magnus “great”; scientific uses include earthquake strength and stellar brightness.','magnitude'),contexts:[C('magnitude.s3','地震报告','The quake had a magnitude of 6.5, and officials warned residents to expect aftershocks across the surrounding region.','这次地震震级为 6.5，官员提醒居民周边地区可能会有余震。','The quake had / a magnitude of 6.5 / and officials warned residents / to expect aftershocks across the surrounding region.','magnitude 作科学名词，数字表示地震强度等级。','地震报告中的 6.5 震级符合 s3。')],mistakes:[M('The report gave the quake a magnitude of 6.5 but explained that magnitude measures the storm’s rainfall.','The report used magnitude to state the earthquake’s strength.','这里 magnitude 衡量地震强度，不是降雨量。')],quiz:[Q('The magnitude of a storm may describe its?','size or extent','uniform colour','postal route','size or extent','magnitude 可指事物的大小或范围。'),Q('The magnitude of a decision may mean its?','importance or seriousness','temperature','number of pages','importance or seriousness','该词也指事情的重要性或严重程度。'),Q('A quake magnitude is a number for?','earthquake strength','the number of witnesses','the age of a palace','earthquake strength','科学义可用数值表示地震强度。'),Q('What was the earthquake magnitude?','6.5','0.5','65 litres','6.5','报告给出的数值是 6.5。')]});
D('maid',{etymology:E('Maid is a shortened form of maiden; it first meant a young unmarried woman and later commonly named a female domestic servant.','maid'),contexts:[C('maid.s1','酒店服务','The maid changed the sheets and left fresh towels in the guest room before the family returned from the museum.','一家人从博物馆回来前，女服务员更换了床单，并在客房里放好干净毛巾。','The maid changed the sheets / and left fresh towels / in the guest room / before the family returned.','maid 作名词，指在家庭或酒店受雇做清洁家务的女性。','更换床单和补充毛巾属于酒店清洁工作，符合 s1。')],mistakes:[M('The maid changed the sheets, meaning the hotel’s building itself was replaced by a woman.','The maid was the hotel worker who changed the bed linen.','maid 指受雇的工作人员，不是酒店建筑。')],quiz:[Q('A maid may be employed to do?','cleaning and housework','write song lyrics','hear court cases','cleaning and housework','maid 的常见义是家庭或酒店清洁人员。'),Q('In older literary use, a maid can mean?','a young unmarried woman','a machine part','a powerful business owner','a young unmarried woman','maid 还有旧式文学中的年轻未婚女子义。'),Q('What did the maid leave in the guest room?','fresh towels','a magenta poster','a steel magnet','fresh towels','语境说她放下干净毛巾。'),Q('Which room did she prepare?','the guest room','the courtroom','the rainforest canopy','the guest room','她整理的是客房。')]});
D('maiden',{etymology:E('Maiden comes from Old English mægden, a form related to mægð, “young woman”; it also developed the adjective senses “first” and “before marriage.”','maiden'),contexts:[C('maiden.s2','首航报道','The ship completed its maiden voyage without incident, and the crew celebrated when it reached the home port.','这艘船顺利完成了首航，船员抵达母港时举行了庆祝。','The ship completed / its maiden voyage / without incident / and the crew celebrated at the home port.','maiden 修饰 voyage，表示首次发生的航行。','船只第一次航行符合 s2。')],mistakes:[M('The ship’s maiden voyage was its final trip after hundreds of earlier voyages.','Its maiden voyage was the first trip the ship made.','已有数百次航行后再出发并非 maiden voyage。')],quiz:[Q('A maiden in older usage is a?','young unmarried woman','ship’s metal armour','scientific measurement','young unmarried woman','maiden 的旧式名词义指年轻未婚女子。'),Q('A maiden voyage is a ship’s?','first voyage','last voyage after many years','voyage carrying only mail','first voyage','maiden 修饰 voyage 表示首次航行。'),Q('Maiden name means a woman’s surname?','before marriage','after retirement','chosen by a ship’s captain','before marriage','maiden name 指婚前姓氏。'),Q('What happened after the maiden voyage?','the crew celebrated at home port','the ship returned before leaving','the crew became magistrates','the crew celebrated at home port','船抵达母港后船员庆祝。')]});
D('mail',{etymology:E('Mail has several histories: correspondence is linked to French words for a bag or packet, while armour mail is related to French maille, “mesh or ring”; the histories should not be conflated.','mail'),contexts:[C('mail.s1','邮政服务','The mail arrived late today, so several parcels for the village shop were delivered after closing time.','今天邮件送达得较晚，村里商店的几个包裹在关门后才送到。','The mail arrived late / today / so several parcels for the village shop / were delivered after closing time.','mail 作不可数集合名词，指信件包裹或投递系统。','迟到的包裹属于邮政投递义 s1。')],mistakes:[M('The mail arrived late, meaning a suit of metal rings was delivered to every household.','The mail consisted of letters and parcels delivered late.','现代邮政义不是金属环甲。')],quiz:[Q('Mail can mean letters and?','parcels','machines','mackerel','parcels','mail 指信件和包裹。'),Q('Electronic mail is?','messages sent online','armour made of metal rings','a magazine’s cartridge holder','messages sent online','mail 也可指电子邮件。'),Q('To mail a form is to?','send it','magnify it','wear it as armour','send it','mail 可作动词表示寄送。'),Q('Chain mail is armour made of?','metal rings or plates','paper envelopes','soft silk','metal rings or plates','mail 还有金属环或片制成的铠甲义。')]});
D('mailman',{etymology:E('Mailman combines mail and man and names a person employed to deliver letters and parcels; mail carrier is a gender-neutral alternative.','mailman'),contexts:[C('mailman.s1','社区投递','The mailman left the parcel on the front step and rang the bell so the resident would know it had arrived.','邮递员把包裹放在前门台阶上并按了门铃，让住户知道包裹已经送到。','The mailman left the parcel / on the front step / and rang the bell / so the resident would know it had arrived.','mailman 作可数名词，指投递信件和包裹的工作人员。','把包裹送到住户门前符合 s1。')],mistakes:[M('The mailman delivered parcels by keeping them at the depot and never taking them to any address.','The mailman carried the parcel to the resident’s home.','留在邮局未投递与 mailman 的工作相反。')],quiz:[Q('A mailman is employed to deliver?','letters and parcels','court verdicts','sea fish','letters and parcels','mailman 指邮递员。'),Q('Where did the mailman leave the parcel?','on the front step','in a river','inside a magazine','on the front step','语境地点是前门台阶。'),Q('What gender-neutral term may be used?','mail carrier','mail boy only','mail mistress only','mail carrier','mail carrier 不限定性别。','register'),Q('Why did the mailman ring the bell?','to let the resident know the parcel arrived','to signal the train was late','to call a magistrate','to let the resident know the parcel arrived','按门铃是通知住户包裹送达。')]});
D('maim',{etymology:E('Maim came through Old French maheimer, “to injure or cripple”; it can describe severe bodily injury or serious damage to an economy or system.','maim'),contexts:[C('maim.s2','战后经济','Years of conflict maimed the regional economy, leaving small businesses without roads, credit, or reliable electricity.','多年冲突重创了地区经济，使小企业失去道路、信贷和稳定电力。','Years of conflict / maimed the regional economy / leaving small businesses without roads, credit, / or reliable electricity.','maim 作及物动词的比喻义，表示严重损害系统或经济。','冲突使经济失去关键功能，符合 s2。')],mistakes:[M('The conflict maimed the economy by improving every service and leaving businesses stronger than before.','The conflict badly damaged the economy and its ability to function.','全面改善与严重损害相反。')],quiz:[Q('To maim a person is to injure them so badly that?','part of the body cannot be used','they become a magistrate','they gain a new skill','part of the body cannot be used','maim 的身体义指造成严重肢体损伤。'),Q('A conflict can maim an economy by?','damaging it severely','making it more prosperous','publishing a magazine about it','damaging it severely','maim 也可比喻严重破坏经济。'),Q('What did the conflict leave businesses without?','roads, credit, and reliable electricity','lenses and song lyrics','mailmen and mackerel','roads, credit, and reliable electricity','语境列出经济基础设施与资源缺失。'),Q('Maim is generally a?','verb','colour noun','plural adjective','verb','maim 是及物动词。','grammar')]});
D('main',{etymology:E('Main comes from Old English mægen, “strength or power,” and developed the adjective sense “chief or most important”; the noun also names a supply pipe or line.','main'),contexts:[C('main.s2','市政维修','Workers are repairing the water main beneath the avenue, so nearby buildings have been asked to conserve water for the day.','工人正在维修大道下方的供水干管，因此附近建筑被要求当天节约用水。','Workers are repairing / the water main / beneath the avenue / so nearby buildings have been asked to conserve water.','main 作名词，指输送水、气或电的主干管线。','地下供水干管正在维修，符合 s2。')],mistakes:[M('The city repaired the water main, meaning a small kitchen faucet that serves only one sink.','The city repaired the large pipe that supplies water to the area.','main 指主干供水管，不是单个水龙头。')],quiz:[Q('The main entrance is the?','largest or most important entrance','smallest hidden exit','pipe carrying gas','largest or most important entrance','main 作形容词可表示最重要的。'),Q('A water main is a large?','pipe supplying water','magazine article','mail parcel','pipe supplying water','main 作名词可指供水干管。'),Q('In the main means?','for the most part','at the main door only','under a water pipe','for the most part','the main 作名词短语可表示“大体上”。'),Q('Where was the water main being repaired?','beneath the avenue','on the roof','inside the magazine','beneath the avenue','语境说明干管位于大道下方。')]});
D('mainland',{etymology:E('Mainland combines main and land and names the principal landmass, as opposed to nearby islands.','mainland'),contexts:[C('mainland.s1','渡轮线路','The ferry links the island to the mainland, where the nearest hospital and railway station are located.','渡轮连接这座岛屿与本土，最近的医院和火车站都位于本土上。','The ferry links the island / to the mainland / where the nearest hospital / and railway station are located.','mainland 作名词，指与岛屿相对的国家或大陆主体陆地。','渡轮从岛上连接到主要陆地符合 s1。')],mistakes:[M('The ferry links the island to the mainland, meaning another small island separated from the country’s main landmass.','The ferry connects the island with the principal landmass.','另一座离岛不是此处的 mainland。')],quiz:[Q('The mainland is the?','principal landmass apart from surrounding islands','smallest island in an archipelago','area of ocean between islands','principal landmass apart from surrounding islands','mainland 指国家或大陆的主体陆地。'),Q('Mainland prices are prices belonging to?','the main landmass','an offshore island only','a ship’s cabin','the main landmass','mainland 也可作形容词，表示本土的。'),Q('What links the island in the example?','a ferry','a mainsheet','a magazine','a ferry','渡轮连接岛屿与本土。'),Q('Where are the nearest hospital and station?','on the mainland','under the sea','inside a mail parcel','on the mainland','语境说医院和车站位于本土。')]});
D('mainline',{etymology:E('Mainline combines main and line for a principal route; the verb use for injecting a drug directly into a vein is a later colloquial sense.','mainline'),contexts:[C('mainline.s1','铁路出行','The town sits on the mainline to the capital, allowing commuters to reach the city without changing trains.','这座城镇位于通往首都的铁路主线上，通勤者无需换车便可进城。','The town sits / on the mainline to the capital / allowing commuters to reach the city / without changing trains.','mainline 作名词，指铁路的主要干线或活动主流。','城镇位于通往首都的主铁路线，符合 s1。')],mistakes:[M('The town sits on a branch siding far from the principal railway route, so it is on the mainline.','The town sits on the principal railway route to the capital.','支线侧轨不属于主要铁路干线。')],quiz:[Q('A railway mainline is its?','principal route','smallest station room','ticket office','principal route','mainline 名词可指铁路主线。'),Q('To mainline an illegal drug means to?','inject it directly into a vein','mail it to a friend','mix it into a magazine','inject it directly into a vein','该动词有直接静脉注射的词义。'),Q('What does the mainline connect the town to?','the capital','a rainforest','a factory’s water pipe','the capital','语境说铁路通往首都。'),Q('Why is the route useful to commuters?','they can travel without changing trains','they can avoid all rail travel','it carries only mail','they can travel without changing trains','主线让通勤者无需换乘。')]});
D('mainly',{etymology:E('Mainly is formed from the adjective main with the adverb suffix -ly and means for the most part or mostly.','mainly'),contexts:[C('mainly.s1','课程介绍','The evening course is mainly for beginners, although students with some experience may join after speaking with the instructor.','这门夜校课程主要面向初学者，不过有一定经验的学生也可以先和讲师沟通后加入。','The evening course / is mainly for beginners / although students with some experience / may join after speaking with the instructor.','mainly 作副词修饰 for beginners，表示主要针对某群体。','课程对象以初学者为主，符合 s1。')],mistakes:[M('The course is mainly for beginners, meaning every advanced learner is its sole intended student.','The course is mostly intended for beginners.','所有高级学习者为唯一对象与 mainly for beginners 不符。')],quiz:[Q('Mainly means?','for the most part','never under any circumstances','at the main entrance','for the most part','mainly 表示大部分或主要。'),Q('Who is the course mainly for?','beginners','magistrates','mail carriers','beginners','课程主要面向初学者。'),Q('Can experienced students join?','yes, after speaking with the instructor','no one may join','only if they teach the class','yes, after speaking with the instructor','语境允许有经验者先与讲师沟通。'),Q('Mainly is an adverb related to?','main','maim','maize','main','mainly 由 main 加 -ly 构成。','word-formation')]});
D('mainsheet',{etymology:E('Mainsheet combines main sail and sheet, a nautical term for the line used to control a sail.','mainsheet'),contexts:[C('mainsheet.s1','帆船训练','As the wind rose, the sailor eased the mainsheet to let the mainsail move and reduce the pressure on the boat.','风力增强时，水手放松主帆绳，让主帆移动以减轻船只所受的压力。','As the wind rose / the sailor eased the mainsheet / to let the mainsail move / and reduce the pressure on the boat.','mainsheet 作航海名词，指用来调整主帆角度的绳索。','水手调整主帆绳以控制帆和受风压力，符合 s1。')],mistakes:[M('The sailor eased the mainsheet by tightening the boat’s anchor chain and leaving the sail controls untouched.','The sailor adjusted the line that controls the mainsail.','锚链不控制主帆，不能替代 mainsheet。')],quiz:[Q('A mainsheet is a line used to adjust the?','mainsail','mail route','railway mainline','mainsail','mainsheet 用于控制主帆。'),Q('What changed before the sailor eased the line?','the wind rose','the train arrived','the magazine was published','the wind rose','风力增强后水手放松绳索。'),Q('Why ease the mainsheet?','to reduce pressure on the boat','to repair a water main','to deliver a parcel','to reduce pressure on the boat','调整主帆可减轻船只受风压力。'),Q('Mainsheet belongs to?','sailing terminology','court procedure','chemistry','sailing terminology','mainsheet 是航海术语。')]});
D('mainspring',{etymology:E('Mainspring combines main and spring; it first names a watch’s principal spring and is also used figuratively for the chief motive force.','mainspring'),contexts:[C('mainspring.s1','创业动机','Curiosity was the mainspring of her research career, driving her to ask questions that other people had overlooked.','好奇心是她科研生涯的主要动力，促使她提出别人忽略的问题。','Curiosity was / the mainspring of her research career / driving her to ask questions / that other people had overlooked.','mainspring 作比喻名词，表示推动整体运行的主要动力。','好奇心推动她持续研究，符合 s1 的比喻义。')],mistakes:[M('Curiosity was the mainspring of her career, meaning it played no part in motivating her work.','Curiosity was the chief force that drove her career.','毫无作用与主要动力的比喻义相反。')],quiz:[Q('A watch’s mainspring is its?','principal spring','mail compartment','main railway line','principal spring','mainspring 本义是钟表里的主发条。'),Q('Figuratively, the mainspring of a career is its?','chief driving force','least important decoration','final salary','chief driving force','该词也指背后的主要推动力。'),Q('What drove the researcher to ask questions?','curiosity','a mackerel','a magenta coat','curiosity','语境说明好奇心是她的动力。'),Q('Which phrase is natural?','the mainspring of change','the mainspring weighs six litres','a mainspring of the island','the mainspring of change','mainspring 可与 of 连用表示某事的主要动力。','collocation')]});
D('mainstay',{etymology:E('Mainstay combines main and stay, originally a principal supporting rope on a ship; figuratively it means a person or thing that supports a whole.','mainstay'),contexts:[C('mainstay.s1','团队合作','As the team’s mainstay, Priya coordinated schedules, shared equipment, and made sure new members felt welcome.','作为团队的支柱，普里娅协调日程、共享设备，并确保新成员受到欢迎。','As the team’s mainstay / Priya coordinated schedules / shared equipment / and made sure new members felt welcome.','mainstay 作表语名词，指支撑整体的人或物。','她承担多项关键支持工作，符合 s1。')],mistakes:[M('Priya was the team’s mainstay because nobody relied on her and her work never supported the group.','Priya was a key person who helped hold the team together.','无人依靠且不提供支持，与 mainstay 相反。')],quiz:[Q('A team’s mainstay is someone or something that?','supports the whole team','is the least useful part','is a type of fish','supports the whole team','mainstay 指支撑全局的人或物。'),Q('What did Priya coordinate?','schedules','magazine colours','mackerel migration','schedules','语境列出她协调日程。'),Q('A ship’s mainstay was originally a supporting?','rope','magazine','court','rope','该词源自船上的主要支撑索具。'),Q('Which phrase fits the figurative use?','the mainstay of the project','the mainstay is a fish','mainstay into a verb','the mainstay of the project','可说某人是项目的支柱。','collocation')]});
D('mainstream',{etymology:E('Mainstream combines main and stream and developed the metaphorical meaning of the opinions, styles, or activities accepted by most people.','mainstream'),contexts:[C('mainstream.s1','社会趋势','The once-unusual idea has entered the mainstream, appearing in school courses, public debates, and national policy.','这个曾经不寻常的观念已进入主流，出现在学校课程、公共讨论和国家政策中。','The once-unusual idea / has entered the mainstream / appearing in school courses / public debates, and national policy.','mainstream 作名词，指多数人接受的意见、风格或活动。','该观念已被广泛接受并进入公共机构，符合 s1。')],mistakes:[M('The idea entered the mainstream even though almost nobody accepted it and it remained entirely unknown.','The idea became widely accepted and entered the mainstream.','无人接受仍完全未知与进入主流相反。')],quiz:[Q('The mainstream is what is?','accepted by most people','rejected by everyone','limited to one private diary','accepted by most people','mainstream 名词指多数人认可的主流。'),Q('A mainstream view is?','accepted by or aimed at ordinary people','known only to one researcher','a specialist machine part','accepted by or aimed at ordinary people','mainstream 也可作形容词表示主流的。'),Q('To mainstream a pupil can mean to?','place the pupil in ordinary classes','remove the pupil from all education','make the pupil a mailman','place the pupil in ordinary classes','该词还可作动词，表示安排进入普通班级。'),Q('Where did the idea appear?','courses, debates, and policy','only a hidden folder','under the sea','courses, debates, and policy','语境列出学校、公众和政策领域。')]});
D('maintain',{etymology:E('Maintain came through Anglo-French maintenir from Latin manu tenere, “hold in the hand”; English developed senses of preserve, care for, assert, and support financially.','maintain'),contexts:[C('maintain.s2','道路养护','The city maintains the rural roads by filling cracks each spring and clearing drainage ditches before the rainy season.','市政府每年春天填补裂缝，并在雨季前清理排水沟，以维护乡间道路。','The city maintains the rural roads / by filling cracks each spring / and clearing drainage ditches / before the rainy season.','maintain 作及物动词，表示使道路保持良好状态。','定期修补和清理道路基础设施符合 s2。')],mistakes:[M('The city maintains its roads by leaving every crack unrepaired and allowing drains to remain blocked.','The city repairs the roads and clears drains to keep them in good condition.','放任损坏不属于维护道路。')],quiz:[Q('To maintain a level means to?','keep it at the same level','make it disappear','deny that it exists','keep it at the same level','maintain 可表示使状态保持不变。'),Q('A city maintains roads by?','keeping them in good condition','selling them to drivers','making them unusable','keeping them in good condition','道路维护是保持其良好状态。'),Q('She maintains that she was not there means she?','firmly says it is true','repairs a building','pays someone’s rent','firmly says it is true','maintain 还可表示坚定声称。'),Q('To maintain one’s parents can mean to?','provide money for their living','argue that they are wrong','make them wait outside','provide money for their living','maintain 还有供养某人的用法。')]});
D('maintenance',{etymology:E('Maintenance is formed from maintain with the noun suffix -ance and refers to upkeep or the continuation of a state.','maintenance'),contexts:[C('maintenance.s1','车辆保养','Regular maintenance keeps the delivery vans safe, so the company checks brakes, tyres, and lights before each long trip.','定期维护能保障送货车的安全，因此公司每次长途出发前都会检查刹车、轮胎和车灯。','Regular maintenance / keeps the delivery vans safe / so the company checks brakes, tyres, and lights / before each long trip.','maintenance 作不可数名词，指使车辆保持良好状态的维护工作。','定期检查车辆部件符合 s1。')],mistakes:[M('The vans needed maintenance, but the company ignored every fault and let their brakes fail.','The company inspected and repaired the vans to keep them safe.','放任故障不处理与 maintenance 相反。')],quiz:[Q('Vehicle maintenance means?','keeping the vehicle in good condition','selling the vehicle','changing its colour only','keeping the vehicle in good condition','maintenance 指保养维护。'),Q('What parts did the company check?','brakes, tyres, and lights','lyrics, luster, and loam','mail and magazines','brakes, tyres, and lights','语境列出三项车辆检查内容。'),Q('Maintenance can also mean keeping a situation?','going','secret forever','underwater','going','该词还可指维持某种状态。'),Q('When were the vans checked?','before each long trip','only after being scrapped','during a court hearing','before each long trip','公司在每次长途出发前检查。')]});
D('maize',{etymology:E('Maize came into English through Spanish maíz, from Taíno mahís, the name used for the crop in the Caribbean.','maize'),contexts:[C('maize.s1','农作物观察','Maize is grown across the region, and farmers harvest the grain in autumn for food and animal feed.','这一地区广泛种植玉米，农民在秋季收获籽粒，用作食物和动物饲料。','Maize is grown / across the region / and farmers harvest the grain / in autumn for food and animal feed.','maize 可指玉米植株，也可指其籽粒；本句先作作物名。','农民种植并收获玉米籽粒符合 s1。')],mistakes:[M('The farmer planted maize, a sea fish that grows in salt water.','The farmer planted a tall grain crop.','maize 是谷物作物，不是海鱼。')],quiz:[Q('Maize is a crop grown for its?','grain','metal','animal skin','grain','maize 是以籽粒为主要收获物的作物。'),Q('When did the farmers harvest the grain?','in autumn','in the middle of winter only','before planting','in autumn','语境说秋季收获。'),Q('Maize can refer to the plant or?','its grain','a railway route','a magistrate','its grain','maize 也可指玉米籽粒。'),Q('Which language passed maize into English?','Spanish','French only','Old Norse','Spanish','英语 maize 经由西班牙语而来。','meaning')]});
D('majestic',{etymology:E('Majestic is formed from majesty with the adjective suffix -ic and means impressively grand and beautiful.','majestic'),contexts:[C('majestic.s1','山谷远眺','The majestic castle overlooked the valley, its towers rising above the morning mist and the surrounding forest.','壮丽的城堡俯瞰山谷，塔楼高耸于晨雾和周围森林之上。','The majestic castle / overlooked the valley / its towers rising above the morning mist / and the surrounding forest.','majestic 修饰 castle，表示景象壮观、庄严。','高耸塔楼和山谷景观符合 s1。')],mistakes:[M('The castle was majestic although it was unimpressive, tiny, and visually plain.','The castle was impressively grand and beautiful.','渺小平庸与 majestic 相反。')],quiz:[Q('A majestic castle is?','impressively grand and beautiful','small and unimpressive','a scientific instrument','impressively grand and beautiful','majestic 表示壮观庄严。'),Q('What did the castle overlook?','the valley','a magazine rack','a railway tunnel','the valley','城堡俯瞰山谷。'),Q('What rose above the mist?','the towers','the mail','the maize crop','the towers','语境中塔楼高出晨雾。'),Q('Majestic is related to the noun?','majesty','majority','mackerel','majesty','majestic 由 majesty 加 -ic 构成。','word-formation')]});
D('majesty',{etymology:E('Majesty came through Old French from Latin maiestas, “greatness or dignity”; it also forms part of royal forms of address.','majesty'),contexts:[C('majesty.s1','山岳景色','They watched the majesty of the mountains at sunrise, when the peaks glowed above the clouds.','日出时分，他们凝望群山的壮丽，山峰在云层上方泛着光。','They watched / the majesty of the mountains / at sunrise / when the peaks glowed above the clouds.','majesty 作名词，表示令人敬畏的宏伟与庄严。','群山在日出时的壮丽景象符合 s1。')],mistakes:[M('They admired the majesty of the mountains because the view was completely unimpressive and ordinary.','They admired the mountains’ grand and dignified beauty.','毫不起眼与 majesty 的庄严宏伟相反。')],quiz:[Q('Majesty can mean a quality of being?','grand and dignified','tiny and commonplace','expensive to mail','grand and dignified','majesty 的常见义是宏伟庄严。'),Q('Your Majesty is a title used for?','a king or queen','a mail carrier','a university student','a king or queen','该词还用于称呼国王或女王。'),Q('When did the mountains glow?','at sunrise','during a court hearing','after the magazine closed','at sunrise','语境中的山峰在日出时发光。'),Q('What did the observers watch?','the mountains','a mainsheet','a macaw','the mountains','观察者欣赏的是群山景色。')]});
D('major',{etymology:E('Major comes from Latin maior, “greater,” the comparative form of magnus “great”; English uses it as adjective, noun, and verb.','major'),contexts:[C('major.s4','大学选课','She decided to major in law after taking an introductory course and speaking with two practising attorneys.','她在修读导论课程并与两位执业律师交谈后，决定主修法律。','She decided / to major in law / after taking an introductory course / and speaking with two practising attorneys.','major 作不及物动词，major in + 学科表示主修某专业。','大学把法律作为主修课程符合 s4。')],mistakes:[M('She majored law without the preposition in required in this construction.','She majored in law.','表示主修某学科时标准结构是 major in。','grammar')],quiz:[Q('A major problem is?','more important or serious than others','the least important issue','a type of mail','more important or serious than others','major 作形容词可表示重要或严重。'),Q('A student’s major is?','the main subject studied at college','their postal address','a military uniform','the main subject studied at college','major 作名词可指大学主修科目。'),Q('An army major is?','an officer above a captain','a student’s course','a person who repairs roads','an officer above a captain','major 也指高于上尉的军官。'),Q('Which phrase means study law as the main subject?','major in law','major law at','major of law','major in law','动词结构是 major in + 学科。','collocation')]});
D('majority',{etymology:E('Majority came through French from Medieval Latin maioritas, based on maior “greater”; it usually means the greater number, often more than half.','majority'),contexts:[C('majority.s1','投票统计','The majority voted in favour of the proposal, although a small group asked the committee to review its costs.','多数人投票支持这项提案，不过仍有一小部分人要求委员会重新审查成本。','The majority voted / in favour of the proposal / although a small group / asked the committee to review its costs.','majority 作名词，表示数量较多的一方；谓语形式可能依语境而定。','支持票多于反对票符合 s1。')],mistakes:[M('The majority voted in favour even though fewer people supported the proposal than opposed it.','More people supported the proposal than opposed it.','支持人数较少不能称为支持方占多数。')],quiz:[Q('A majority is?','the greater number of people or things','a single person','the smallest possible group','the greater number of people or things','majority 指数量较多的一方。'),Q('How did most people vote?','in favour of the proposal','against it unanimously','they did not vote','in favour of the proposal','语境说多数投票支持提案。'),Q('Who requested a cost review?','a small group','the entire majority only','the mailman','a small group','要求审查成本的是一小部分人。'),Q('Majority is related to which adjective?','major','maize','magnetic','major','majority 与 major 同源。','word-formation')]});
D('make',{etymology:E('Make comes from Old English macian, “to make or construct,” and has developed many productive senses and phrasal uses.','make'),contexts:[C('make.s1','家庭烘焙','She made a cake for the party by mixing flour, eggs, and fruit, then baking it until the centre was firm.','她把面粉、鸡蛋和水果混合后烘烤，做了一个聚会蛋糕，直到中心凝固。','She made a cake / for the party / by mixing flour, eggs, and fruit / then baking it until the centre was firm.','make 作及物动词，表示把原料加工制作成物品。','由材料制作蛋糕符合 s1。'),C('make.s5','产品评价','This watch is a good make, with a durable case and a clear face that is easy to read.','这块表的牌子不错，表壳耐用，表盘清晰易读。','This watch / is a good make / with a durable case / and a clear face that is easy to read.','make 作名词可指产品的厂家或类型；a good make 是常见说法。','这里 make 指产品品牌或制造商，符合 s5。')],mistakes:[M('She made a cake by mixing the ingredients, but the sentence used make to mean she forced the cake to wait outside.','She made a cake by combining ingredients and baking them.','此处 make 表示制作，不是强迫某人做事。')],quiz:[Q('To make a cake is to?','create it from ingredients','force someone to wait','earn a salary','create it from ingredients','make 的常见义是制作。'),Q('The news made her happy means the news?','caused that feeling','manufactured her','paid her wages','caused that feeling','make 可表示造成一种状态或感受。'),Q('A shop makes a profit means it?','earns or gains money','builds a cake','forces a customer','earns or gains money','make 也可表示赚取利润。'),Q('They made him wait outside means they?','forced him to wait','built him a house','named a product brand','forced him to wait','make 可表示强迫某人做某事。')]});
D('make up',{etymology:E('Make up is a phrasal verb formed from make and up; its meanings include inventing a story and applying cosmetics.','make up'),contexts:[C('make up.s1','请假说明','He made up an excuse about a broken train, but his colleague later learned that the service had run normally.','他编造了火车故障的借口，但同事后来得知列车一直正常运行。','He made up an excuse / about a broken train / but his colleague later learned / that the service had run normally.','make up 作短语动词，表示编造故事或借口；宾语可置于 make 与 up 之间。','虚构并不真实的火车故障理由符合 s1。')],mistakes:[M('He made up an excuse by reporting the verified truth exactly as it happened.','He invented an excuse that was not true.','如实报告事实并非编造借口。')],quiz:[Q('To make up an excuse is to?','invent it','repair a railway','maintain a road','invent it','make up 可表示编造理由。'),Q('To make up a face means to?','put cosmetics on it','write a story about it','make it wait outside','put cosmetics on it','make up 也可表示给脸化妆。'),Q('What excuse did he invent?','a broken train','a damaged palace','a missing mackerel','a broken train','语境说他编造列车故障。'),Q('Which word order is possible?','make up an excuse','make an excuse up','both forms can be used','both forms can be used','make up 是可分短语动词，名词宾语可置中或置后。','grammar')]});
D('make use of',{etymology:E('Make use of is a fixed verb phrase using make, use, and of; it means employ something for a particular purpose.','make use of'),contexts:[C('make use of.s1','技术升级','The company made use of new technology to reduce energy consumption without slowing production.','公司利用新技术降低能耗，同时没有减慢生产速度。','The company made use of new technology / to reduce energy consumption / without slowing production.','make use of + 名词表示利用某物；to reduce 说明使用目的。','使用新技术达到节能目的符合 s1。')],mistakes:[M('The company made use of new technology by refusing to employ it and leaving every system unchanged.','The company used the new technology to lower energy consumption.','拒绝使用与 make use of 相反。')],quiz:[Q('To make use of a tool is to?','use it for a purpose','throw it away unused','repair it without touching it','use it for a purpose','该短语表示利用某物。'),Q('What did the company make use of?','new technology','a maiden voyage','a magistrate','new technology','语境中公司利用新技术。'),Q('Why did it use the technology?','to reduce energy consumption','to increase delays','to write a lyric','to reduce energy consumption','使用目的是降低能耗。'),Q('Which pattern is correct?','make use of the opportunity','make use the opportunity of','make the use opportunity of','make use of the opportunity','固定结构是 make use of + 名词。','grammar')]});
D('make-believe',{etymology:E('Make-believe combines make and believe and names pretending that something unreal is real; it can function as a noun or adjective.','make-believe'),contexts:[C('make-believe.s1','儿童游戏','The children built a cardboard castle and lived in a world of make-believe, taking turns to play the captain and the dragon.','孩子们用纸板搭了一座城堡，生活在想象世界里，轮流扮演船长和巨龙。','The children built a cardboard castle / and lived in a world of make-believe / taking turns / to play the captain and the dragon.','make-believe 作名词，指把虚构情境当真的想象游戏。','孩子们假扮角色并编出故事，符合 s1。')],mistakes:[M('The children’s make-believe game was a factual report of events that had really happened.','The children pretended that the invented castle and characters were real.','虚构扮演与真实事件报告相反。')],quiz:[Q('Make-believe is?','pretending something unreal is real','a scientific measurement','a railway route','pretending something unreal is real','make-believe 指假装和想象。'),Q('What did the children build?','a cardboard castle','a working maglev','a courthouse','a cardboard castle','语境中的道具是纸板城堡。'),Q('Who did they pretend to be?','a captain and a dragon','a mailman and a magistrate only','two real reporters','a captain and a dragon','孩子们轮流扮演船长和巨龙。'),Q('Make-believe can be used as?','a noun or adjective','only a past-tense verb','a currency unit','a noun or adjective','该词可作名词或形容词。','grammar')]});
D('makeover',{etymology:E('Makeover combines make and over and names a treatment or redesign that changes how a person or place looks.','makeover'),contexts:[C('makeover.s1','咖啡馆翻新','The café had a complete makeover last spring, with brighter lighting, new tables, and a fresh coat of paint.','这家咖啡馆去年春天进行了全面改造，换上更明亮的灯光、新桌椅和一层新漆。','The café had / a complete makeover / last spring / with brighter lighting, new tables, and a fresh coat of paint.','makeover 作可数名词，指改变外观的整套改造。','灯光、桌椅和油漆共同改变咖啡馆外观，符合 s1。')],mistakes:[M('The café had a makeover, but its appearance remained exactly the same and nothing was redesigned.','The café was redesigned with new lighting, furniture, and paint.','外观未变且未重新设计与 makeover 相反。')],quiz:[Q('A makeover changes how someone or something?','looks','is measured scientifically','is mailed','looks','makeover 指改变外观的处理或改造。'),Q('When did the café have its makeover?','last spring','in the sixteenth century','before it was built','last spring','语境时间是去年春天。'),Q('What was added or changed?','lighting, tables, and paint','magazine cartridges','a mainland ferry','lighting, tables, and paint','语境列出改造项目。'),Q('A complete makeover is a?','redesign or appearance change','court ruling','kind of maize','redesign or appearance change','makeover 常指整体翻新或形象改造。')]});

})();
